// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_8: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.vampiric-maiden","name":"Vampiric Maiden","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"4d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"4d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4","1":"1d4"}},"counteraction":false,"ritual":null,"description":"A ghostly iron maiden snaps shut on the target and drains its vitality for your gain. This deals 4d4 piercing damage and 4d4 void damage, and the target must attempt a Fortitude save. You gain temporary Hit Points equal to the void damage the target takes (after applying resistances, weaknesses, and the like). You lose any remaining temporary Hit Points after 1 minute.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target is briefly trapped within the vampiric maiden. The target takes full damage and is by the iron maiden for 1 round or until it uses an Interact action to extricate itself, whichever comes first.\n\nCritical Failure The target takes double damage and is immobilized by the vampiric maiden for 1 round or until it Escapes (the DC is your spell DC), whichever comes first.\nHeightened (+1) The piercing and void damage increase by 1d4 each.","source":{"provider":"PAIZO","sourceId":"07xYlmGX32XtHGEt","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.vapor-form","name":"Vapor Form","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","concentrate","manipulate","polymorph"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target transforms into a vaporous state. In this state, the target is amorphous. It loses any item bonus to AC and all other effects and bonuses from armor, and it uses its proficiency modifier for unarmored defense. It gains resistance 8 to physical damage and is immune to precision damage. It can't cast spells, activate items, or use actions that have the attack or manipulate trait. It gains a fly Speed of 10 feet and can slip through tiny cracks. The target can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"V8wXOsoejQhe6CyG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.variable-gravity","name":"Variable Gravity","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can adjust how strongly gravity grips you, changing between low gravity, normal gravity, and high gravity with ease. Choose one type of gravity when you cast the spell. While the spell lasts, you can change the type of gravity with a single action, which has the concentrate trait. The spell doesn't alter your physical appearance, so it's impossible to what type of gravity you're subjected to by casual observation.\n- Low Gravity You can jump double the normal distance when you or , though still to a maximum of your Speed. When you High Jump, you can use the calculation for a Long Jump but don't double the distance. Rather than the normal calculation for falling damage, when you fall, you take no damage for the first 10 feet and then take bludgeoning damage equal to a quarter of the remaining distance you fell. Abilities that adjust how much falling damage you take still apply.\n- High Gravity You become . You gain a +2 status bonus to your saving throws and DCs to resist forced movement and attempts to knock you . You reduce the distance forced movement moves you by half or 10 feet, whichever is more. You can only jump half as high and far. Rather than the normal calculation for falling damage, you take bludgeoning damage equal to the distance you fall. Abilities that adjust how much falling damage you take still apply.\nHeightened (6th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"DcmWrD0V5PWQQyDm","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vicious-howl","name":"Vicious Howl","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You howl with passion for your cause, empowering yourself to push beyond your limits. You gain a number of temporary Hit Points equal to your level and a +4 circumstance bonus to damage. If you reduce a fiend to 0 Hit Points during this duration, you regain a number of Hit Points equal to the creature's level.","source":{"provider":"PAIZO","sourceId":"z9pIChNg9PmPmn31","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vision-of-beauty","name":"Vision of Beauty","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","emotion","illusion","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a phantasmal image of the most beautiful creature imaginable to the target at a location somewhere within the spell's range. Only the spell's target can see the beauty, though you can see the vague shape of the illusion as it manifests. The effect of the vision is based on the outcome of the target's Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is intrigued by the vision, becoming Stupefied 1 for 1 round.\n\nFailure The target is entranced by the vision, becoming stupefied 1 for 1 round and moving toward the image's location via the most direct route possible for 1 round, bypassing any obvious hazards and enemies in the way. The target is then by the illusion for 1 round.\n\nCritical Failure As failure, except the target is Stupefied 2 and becomes fascinated by the illusion for 1 minute instead of 1 round.\n\nHeightened (+2) You can target an additional creature in range.","source":{"provider":"PAIZO","sourceId":"jqb52wy7A0Eqwuzx","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vision-of-death","name":"Vision of Death","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","death","emotion","fear","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"8d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You force the target to see a vision of its own death. It takes 8d6 mental damage with a Will save. If the target is reduced to 0 HP by this spell, its vision becomes reality and kills it instantly.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and is Frightened 1.\n\nFailure The target takes full damage and is Frightened 2.\n\nCritical Failure The target takes double damage, is Frightened 4 and is for as long as it's frightened.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"Jmxru8zMdYMRuO5n","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.vital-beacon","name":"Vital Beacon","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Vitality radiates outward from you, allowing others to supplicate and receive healing. Once per round, either you or an ally can use an Interact action to supplicate and lay hands upon you to regain Hit Points. Each time the beacon heals someone, it decreases in strength. It restores (@item.rank)d10[healing,vitality|shortLabel] Hit Points to the first creature, (@item.rank)d8[healing,vitality|shortLabel] Hit Points to the second, (@item.rank)d6[healing,vitality|shortLabel] Hit Points to the third, and (@item.rank)d4[healing,vitality|shortLabel] Hit Points to the fourth, after which the spell ends. You can have only one vital beacon active at a time.\n\nHeightened (+1) The beacon restores one additional die of Hit Points each time it heals, using the same die size as the others for that step.","source":{"provider":"PAIZO","sourceId":"ikSb3LRGnrwXJBVX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vital-luminance","name":"Vital Luminance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["aura","cleric","focus","light","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Drawing life force into yourself, you become a beacon of vitality. You glow with bright light in a 30-foot emanation (and dim light to the next 30 feet), and you gain an internal pool of light called a luminance reservoir, which begins with a value of 4. At the start of each of your turns, increase your reservoir by 4.\n\nIf an undead creature damages you with an attack or spell while it's within the bright light of your aura, that creature takes vitality damage equal to half your luminance reservoir value. It takes this damage only the first time it damages you in a round.\n\nYou can Dismiss this Spell. When you do, you can target a creature within your light and direct the vital energy into it. The target must be a willing living creature or an undead creature. This heals a living target or deals vitality damage to an undead target equal to your luminance reservoir's value.\n\nIf you Cast this Spell again, any previous casting ends.\n\nHeightened (+1) Both the initial value of your luminance reservoir and the amount you gain each turn increase by 1.","source":{"provider":"PAIZO","sourceId":"8XuNn0h0rHE24m3B","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.waking-dream","name":"Waking Dream","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cloud the target's mind with vivid, dreamlike imagery, so they have difficulty distinguishing real threats from imagined ones.\nCritical Success The target is unaffected.\n\nSuccess The target is distracted by the visions and treats all other creatures as for 1 round, and you can't Sustain the Spell to increase the duration.\n\nFailure The target is . In addition to the creatures present, the target might also attack wildly at thin air, attempting to fend off the dreams. It can attempt a new save at the end of each of its turns to end the confusion. Even if the confused effect ends early, the target treats all other creatures as concealed for 1 round.\n\nCritical Failure As failure, but the target gets no save to end the effect early.","source":{"provider":"PAIZO","sourceId":"OmhnoYOzFhrp6rXv","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-fire","name":"Wall of Fire","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You raise a blazing wall that burns creatures passing through it. You create either a 5-foot-thick wall of flame in a straight line up to 60 feet long and 10 feet high, or a 5-foot-thick, 10-foot-radius ring of flame with the same height. The wall stands vertically in either form; if you wish, the wall can be of a shorter length or height. Everything on each side of the wall is from creatures on the opposite side. Any creature that crosses the wall or is occupying the wall's area at the start of its turn takes 4d6 fire damage.\n\nHeightened (+1) The fire damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"IarZrgCeaiUqOuRu","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wall-of-mirrors","name":"Wall Of Mirrors","kind":"SPELL","rank":4,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"sHvzaQ6nB5kQUABr","formula":"4d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a solid wall of shimmering reflective glass up to 50 feet long and 20 feet high. The wall is an inch thick and stands vertically. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. Each 10-foot-by-10-foot section of the wall has AC 10, Hardness 10, and 40 Hit Points, and it's immune to critical hits and precision damage. Everything on each side of the wall is from creatures on the opposite side. If a creature Strikes the wall, the wall causes the creature to endure the mental anguish of that attack's pain as well; the creature takes 4d4 mental damage and can resist this damage with a basic Will save.\nHeightened (+1) The Hit Points of each section of the wall increase by 10.","source":{"provider":"PAIZO","sourceId":"eONVFSbBiqaDLGey","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.weapon-storm","name":"Weapon Storm","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 30-foot cone or 10-foot emanation\nYou swing a weapon you're holding, and the weapon magically multiplies into duplicates that swipe at all creatures in either a cone or an emanation. This flurry deals four dice of damage to creatures in the area. This damage has the same type as the weapon and uses the same die size. Determine the die size as if you were attacking with the weapon; for instance, if you were wielding a two-hand weapon in both hands, you'd use its two-hand damage die.\nCritical Success The creature is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage.\n\nCritical Failure The target takes double damage and is subject to the weapon's critical specialization effect.\nHeightened (+1) Add another damage die.","source":{"provider":"PAIZO","sourceId":"8M03UxGXjYyDFAoy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.weaponize-secret","name":"Weaponize Secret","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 3 creatures","area":null},"duration":{"text":"1 minute or until discharged","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You understand that holding a secret is in itself a kind of power. Each target must attempt a Will save.\nSuccess The target is unaffected.\n\nFailure A rune symbolizing a secret the target is keeping (at the GM's discretion) appears floating in front of you. If that creature attempts a Strike or spell attack against you while you hold their secret, you can discharge the rune as a reaction to deal 7d6[mental] damage to the creature.\n\nCritical Failure As failure, but the target becomes convinced you know their secret and takes 1d6[persistent,mental] damage from worry. If the rune with the secret is discharged while the creature is still taking the persistent mental damage, the persistent mental damage immediately ends.\nHeightened (+1) The mental damage increases by 2d6, and the persistent mental damage on a critical failure increases by 1.","source":{"provider":"PAIZO","sourceId":"TRpUjBNPQz3Eshaq","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.web-of-influence","name":"Web of Influence","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["detection"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You learn the location of the nearest creature to whom the target is connected in a magical manner. A creature sustaining a spell on the target is connected to it for the purposes of this spell, as are any creatures who are targets of a spell effect currently affecting the target (such as all the targets of a spell), members of a coven, and creatures that are magically bonded to the target (such as with the ritual). The GM is the final arbiter of whether a creature is magically connected to the target. If you already know individuals who are magically connected to the target, you can exclude them from the spell.\n\nThis spell doesn't tell you anything about the nearest magically connected creature other than its current distance and direction. If the nearest creature is on a different plane the spell indicates this but doesn't reveal which plane.","source":{"provider":"PAIZO","sourceId":"HqZ1VWIcXXZXWm3K","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.whispers-of-the-void","name":"Whispers of the Void","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["auditory","concentrate","manipulate","void"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You whisper baleful secrets that transcend language and carry magically to the ears of your foes. The words take physical form, weakening the life force of the targets, each of which must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes (floor(@item.rank/2))d8[persistent,void] damage.\n\nFailure The creature takes (floor(@item.rank/2)*2)d8[persistent,void] damage and becomes Drained 1.\n\nCritical Failure The creature takes (floor(@item.rank/2)*2)d8[persistent,void] damage and becomes Drained 2 and Doomed 1.\nHeightened (+2) The persistent void damage increases by 1d8 on a success, or by 2d8 on a failure or critical failure.","source":{"provider":"PAIZO","sourceId":"FwW2asotQE8dH1WP","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wild-feast","name":"Wild Feast","kind":"RITUAL","rank":4,"rarity":"RARE","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"TEXT","text":"centered on you"},"area":{"shape":"BURST","feet":500}},"duration":{"text":"3 days","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (mythic)","secondaryChecks":"Diplomacy, Survival","secondaryCasters":2},"description":"You draw forth latent hostility in the local flora and fauna. Even domesticated animals might turn on their owners.\nCritical Success As success, except that animal companions, pets, familiars with the animal, fungus, or plant trait, and similar creatures (subject to the GM's discretion) are also initially affected. Each day for the duration, during daily preparations, its master must succeed at a diplomacy or nature check against a DC equal to the ritual's casting DC or the creature temporarily loses the minion trait and can't be Commanded that day. The creature remains near its master but doesn't help them in any way.\n\nSuccess Carnivorous animals and plants in the area are automatically hostile toward humanoids and other natural enemies. Animal companions, pets, familiars with the animal, fungus, or plant trait, and similar creatures don't turn on their masters, but attempts to or to any creatures with the animal, fungus, or plant trait take a –2 status penalty.\n\nFailure The ritual has no effect.\n\nCritical Failure A terrible hunger awakens within the casters. Each caster is permanently cursed to hunger for the taste of flesh of their own ancestry; this is identical to the ghoul's forbidden cravings curse, except the raw meat must be from a member of their own ancestry. The DC of this curse is equal to the ritual's casting DC.\nHeightened (+2) Double the ritual's area.","source":{"provider":"PAIZO","sourceId":"5y3RlXMDPovOmrhp","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wild-winds-stance","name":"Wild Winds Stance","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["air","focus","manipulate","monk","stance"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until you leave the stance","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take on the stance of the flowing winds, sending out waves of energy at a distance. You can make wind crash unarmed Strikes as ranged Strikes against targets within 30 feet. These deal 1d6 bludgeoning damage; are in the brawling group; and have the agile, nonlethal, propulsive, and unarmed traits. Wind crash Strikes ignore Concealment and all cover.\n\nWhile in wild winds stance, you gain a +2 circumstance bonus to AC against ranged attacks.","source":{"provider":"PAIZO","sourceId":"SkarN4VlNxSJSJNw","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wind-whispers","name":"Wind Whispers","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","linguistic","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth numerous breezes in which you weave gossip, whispering subtly into the ears of those around. Choose a rumor or information you wish to spread, which may or may not be true, about a single subject. Those within range of the spell overhear the rumor at some point over the next hour, though they'll be unable to pin it down to a source. Attempt a check with a modifier equal to your spell DC - 10 against a hard DC for your level. The GM might modify the DC depending on how plausible the rumor is. Repeated castings to spread the same rumor or information have no effect unless circumstances have substantially changed, as determined by the GM.\n\nCritical Success Your rumor spreads far and wide, and it's at the tip of people's tongues. For 1 week, anyone who succeeds at a check to Gather Information on the specific subject learns your rumor in preference to other rumors about the subject. Skill checks to convince people that the rumor is true get a +2 circumstance bonus.\n\nSuccess Enough people take note of the rumor that it begins to spread, though those who heard the rumor aren't necessarily convinced. For 1 week, anyone who succeeds at a check to Gather Information on the specific subject adds your rumor to the list of rumors they could learn about the subject, and skill checks to convince people that the rumor is true get a +1 circumstance bonus.\n\nFailure Most in the area dismiss the rumor as wild gossip and pay it little mind, granting no effect.\n\nCritical Failure The winds' gossip is misinterpreted and spreads information contradictory to the rumor you were attempting to spread. A contradictory rumor spreads, and skill checks to convince others that your original rumor is true take a -2 circumstance penalty.","source":{"provider":"PAIZO","sourceId":"i06YFOtfGfpUvcD7","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.winning-streak","name":"Winning Streak","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"1 creature","area":null},"duration":{"text":"1 round (see text)","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target is energized by its good fortune as it spreads to others-as long as they keep winning. It gains the condition for 1 round. If the target or one of their allies within 20 feet gets a critical success on an attack roll against a significant foe, whoever got the critical success becomes quickened if they weren't already, and the duration of the winning streak is extended by another round. Creatures quickened by the spell can use the extra action to Strike, Step, or Stride. If a full round passes without the target or one their allies critically succeeding on an attack roll against a significant foe, the winning streak breaks and the spell ends.","source":{"provider":"PAIZO","sourceId":"EGTTGI1pkmsVPqHp","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wood-walk","name":"Wood Walk","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","wood"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Wood shapes itself according to your will readily, making staircases appear as you climb up the side of a tree, automatically weaving vines into ladders, or lowering branches to lift you up to the top. When you Cast this Spell, move up to your Speed in any direction or along any surface, so long as there are living plants or trees of size Large or larger within 15 feet of you. The wood allows you to move but doesn't protect you from hazardous terrain or other dangers. Each time you Sustain this spell, you can move again in the same way.\nHeightened (8th) The duration of this spell becomes 10 minutes. You no longer need to Sustain the spell to extend its duration, but you can Sustain it to move as described.","source":{"provider":"PAIZO","sourceId":"Up4zLmZDgciUDpIv","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.word-of-freedom","name":"Word of Freedom","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utter a liberating word of power that frees a creature. You suppress one of the following conditions of your choice: , , , , or . The target isn't affected by the chosen condition, and if you suppress the Grabbed or Restrained condition, the target automatically breaks free from the grab or restraint when you Cast the Spell.\n\nIf you don't remove the effect that provided the condition, the condition returns after the spell ends. For example, if a spell was making the target Confused for 1 minute, word of freedom would let the target act normally for a round, but the Confused condition would return afterward.","source":{"provider":"PAIZO","sourceId":"2jB9eyX7YekwoCvA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wordsmith","name":"Wordsmith","kind":"SPELL","rank":4,"rarity":"RARE","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 document written by a single author and comprised of written text in a single language","area":null},"duration":{"text":"until the next time you Refocus","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You're a devotee of knowledge with an unmatched command of the language used to spread that knowledge, and you can reshape the written word into a form more understandable to your audience. The language of the target's written text shifts to a language you know. This shift doesn't change the text's contents beyond minor translation differences, nor does it grant the reader any understanding of the original language.","source":{"provider":"PAIZO","sourceId":"mSM659xN2VIAHiF3","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ymeris-mark","name":"Ymeri's Mark","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["concentrate","curse","detection","fire","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"wKqdAiiIiDLodRJm","formula":"5d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"wKqdAiiIiDLodRJm":"2d6"}},"counteraction":false,"ritual":null,"description":"You place the fiery mark of the Queen of the Inferno on the target, burning into the creature's very essence. The mark gives off a heat that only you can sense; as long as you're on the same plane as the target, you can sense the direction it's in. The target is and can't reduce the value of this condition normally.\n\nYou can detonate the mark at any point during its duration by Dismissing the spell. The rune explodes in a centered on the target that deals 5d6 fire damage with a basic Reflex save. You choose whether the mark's target is included in the explosion.\n\nWhen you cast the spell, the target attempts a Fortitude save to determine how long the mark lasts. If the spell's duration elapses, the rune doesn't detonate.\nCritical Success The target is unaffected.\n\nSuccess The duration is 1 minute.\n\nFailure The duration is 1 week.\n\nCritical Failure The duration is unlimited.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"6gEKZaGdH842RF3J","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.zeal-for-battle","name":"Zeal for Battle","kind":"SPELL","rank":4,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","fortune","mental"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"you and the triggering ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You and at least 1 ally are about to roll initiative.\n\nYou stoke the righteous anger within yourself and an ally. You and the target ally each roll a d20 and use the higher result for both your initiative rolls. You each still use your own Perception modifier or other statistic to determine your results.","source":{"provider":"PAIZO","sourceId":"I8CPe9Pp7GABqOyB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.zephyr-slip","name":"Zephyr Slip","kind":"SPELL","rank":4,"rarity":"COMMON","traits":["air","manipulate","move"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature enters a space within 5 feet of you.\n\nAn arresting breeze sweeps you up in an instant and moves you to safety. You Fly 15 feet directly away from the triggering creature.\n\nHeightened (6th) You and one adjacent ally Fly up to 25 feet directly away from the triggering creature.\n\nHeightened (8th) You and up to 5 allies within 30 feet Fly up to 25 feet directly away from the triggering creature.","source":{"provider":"PAIZO","sourceId":"FL1OxeOUDzsJYfY4","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aberrant-form","name":"Aberrant Form","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Harnessing the power of vile entities, you transform yourself into a Large aberration. You must have enough space to expand into or the spell is lost. When you cast this spell, choose chuul, gogiteth, gug, or otyugh. While in this form, you gain the aberration trait. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 18 + your level. Ignore your armor's check penalty and Speed reduction.\n- 13 temporary Hit Points.\n- Darkvision.\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +18, and you use the listed damage. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n- Athletics modifier of +20, unless your own modifier is higher.\nYou also gain specific abilities based on the type of aberration you choose:\n- Chuul\n- Speed 30 feet, swim 25 feet;\n- Melee 1 claw (reach 10 feet), Damage 2d8+8 bludgeoning, and you can spend an action after a hit to Grab the target.\n\n- Gogiteth\n- Speed 40 feet, climb 30 feet;\n- Melee 1 jaws, Damage 2d10+8 piercing, and you can spend an action after a hit to Grab the target;\n- Melee 1 leg (agile, reach 10 feet), Damage 2d6+8 piercing.\n\n- Gug\n- Speed 40 feet, climb 20 feet;\n- Melee 1 claw (agile, reach 10 feet), Damage 2d8+8 slashing;\n- your multiple joints allow you to fit through tight spaces as if you were a Medium creature.\n\n- Otyugh\n- +2 circumstance bonus on saves against disease;\n- Speed 20 feet;\n- Melee 1 jaws, Damage 3d6+8 piercing;\n- Melee 1 tentacle (agile, reach 10 feet), Damage 2d6+8 bludgeoning.\n\nHeightened (6th) Your battle form is Huge, and the reach of your attacks increases by 5 feet. You must have space to expand, or the spell is lost. You instead gain AC = 21 + your level, 26 temporary HP, attack modifier +22, damage bonus +13, and Athletics +23.","source":{"provider":"PAIZO","sourceId":"Fu8Ml47ZfXpSYe7E","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.abyssal-plague","name":"Abyssal Plague","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["chaotic","concentrate","disease","evil","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your touch afflicts the target with Abyssal plague, which siphons fragments of their soul away to empower the Abyss. The effect is based on the target's Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 2 spirit damage per spell rank, and takes a -2 status penalty to saves against Abyssal plague for 1 day or until the target contracts it, whichever comes first.\n\nFailure The target is afflicted with Abyssal plague at stage 1.\n\nCritical Failure The target is afflicted with Abyssal plague at stage 2.\n\nAbyssal Plague (disease) Level 9\n\nThe target can't recover from the drained condition from Abyssal plague until the disease is cured\n\nStage 1 Drained 1 (1 day)\n\nStage 2 Drained increases by 2 (1 day).","source":{"provider":"PAIZO","sourceId":"vJuaxTd6q11OjGqA","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.acid-storm","name":"Acid Storm","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["acid","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20,"text":"20-foot-radius burst"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d8","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You evoke a storm of acid rain that pelts the area for the spell's duration. A creature that begins its turn in the area takes 3d8 acid damage (basic Reflex save).\n\nHeightened (+2) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"ZW8ovbu1etdfMre3","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ancestral-winds","name":"Ancestral Winds","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","emotion","fear","manipulate","mental","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"A3N9TKOvgQh5OhDM","formula":"1d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"NPg0qU7objU0x4LJ","formula":"5d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call on the same energies that manifest ancestor storms, summoning wailing spirits to terrorize your foes. Living creatures in the area take 5d6 void damage and 1d6 mental damage and must attempt a Will save. Nonliving creatures are immune to this spell's effects.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is Frightened 1.\n\nFailure The creature takes full damage and is Frightened 2.\n\nCritical Failure As failure, but the creature takes double damage and is Stunned 1.\n\nThe first time each round you Sustain the spell, you can move the area up to 30 feet within the range of the spell. Living creatures in the new area must attempt saves with the same effects as above.","source":{"provider":"PAIZO","sourceId":"Z4X5whSqSvgiiJ05","book":"Pathfinder #209: Destroyer's Doom","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.arcane-countermeasure","name":"Arcane Countermeasure","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"the spell cast by the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range that you can see Casts a Spell.\nYou undermine the target spell, making it easier to defend against. You reduce the spell's rank by 1, and targets of the spell gain a +2 status bonus to any saving throws, skill checks, AC, or DC against it.\n\nYou can't reduce the spell's rank below its minimum. For example, a 5th-rank would remain 5th-rank, but a 5th-rank would become 4th-rank. Targets still gain all the other benefits, even if you don't reduce the spell's rank.","source":{"provider":"PAIZO","sourceId":"h47yv6j6x1pUtzlr","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aspirational-state","name":"Aspirational State","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["incorporeal"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"totems related to the associated goal"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 32 Occultism (master; DC 34 for levels 9-10)","secondaryChecks":"DC 24 Arcana, Athletics, Nature, Occultism, Performance, Religion, or Society (DC 27 for levels 9-10)","secondaryCasters":0},"description":"The primary caster takes an ethereal form composed of the combined drive of every caster to exorcise a malevolent spirit. In this form the primary caster can automatically locate the target of this common goal, and they can orient the secondary casters to this location. The primary caster can't interact with physical objects in this form, but they can interfere with the abilities of other incorporeal creatures, including spirits possessing a physical body. The primary caster can also manifest the collective intent of the ritual's participants as shifts in reality that further the casters' goal. These shifts manifest as Aspiration Points, which the secondary casters can spend on the Material Plane to aid their cause. Using Aspiration Points is described on page 7.\n\nThe magical feedback created by this ritual renders teleportation magic unstable. Any attempt by the casters or the target of the ritual to use an ability with the teleportation trait automatically fails while the ritual is in effect. When the duration expires, the primary caster must spend 1 Aspiration Point to return to the Material Plane; if insufficient Aspiration Points remain, then the primary caster becomes trapped in the Ethereal Plane.\n\nCritical Success The PCs gain 8 Aspiration Points. The strong connection between all the casters gives the secondary casters resistance 5 to void damage for the remainder of the adventure.\n\nSuccess The PCs gain 6 Aspiration Points.\n\nFailure The PCs gain 4 Aspiration Points. The tenuous connection between the casters makes them vulnerable to entropy, giving the secondary casters weakness 5 to void damage for the remainder of the adventure.","source":{"provider":"PAIZO","sourceId":"wrm1zIiLyFD1Is6h","book":"Pathfinder Society Scenario #2-22: Breaking the Storm: Excising Ruination","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.astral-projection","name":"Astral Projection","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"one gem worth a total value of the target's level (minimum 1) × 5 gp, for each target"},"targeting":{"range":{"kind":"TOUCH"},"target":"yourself and up to 5 willing creatures","area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (master)","secondaryChecks":"Arcana or Occultism (whichever isn't used for the primary check), Survival","secondaryCasters":2},"description":"You project the targets' spiritual essences into the Astral Plane, leaving their inanimate physical forms behind. These astral forms can be used to explore the Astral Plane indefinitely, while the targets' bodies remain safely in stasis on the plane where the ritual was cast (where they remain and can't be awoken normally). The casters must be in physical contact with one another in a circle for the duration of the casting, and all targets must be selected from these casters.\n\nA target's astral form is a duplicate of the target and everything they're carrying; anything that happens to a duplicate item happens to the original as well. For instance, if you use, spend, destroy, lose, or give away an item's duplicate, the original vanishes from your possession. For the duration of the ritual, any of the targets can spend a single action to Dismiss their astral form and immediately return to their physical body. As the primary caster, when you Dismiss your astral form, you can also Dismiss all the other targets' astral forms as part of the same action, returning all targets to their physical forms simultaneously. While in the Astral Plane, the other targets are unable to navigate without you, and if they become separated from you, they must wait for your return or Dismiss their own astral forms. When the ritual ends, the targets' astral forms vanish.\n\nA target's astral form and corresponding physical form are linked by an incorporeal silver cord, which is visible only in the Astral Plane. This nearly unbreakable cord serves as conduit and safety line; if severed, the target's astral and physical forms are both immediately slain. If the ritual is interrupted by an external force, such as dispel magic being cast on a target's physical or astral form, the target is immediately and harmlessly returned to their physical body. If a target's astral form is slain, the silver cord immediately rips them back to their physical body; the strain requires them to attempt a Fortitude save with the same DC as the ritual's primary check. On a failure, the creature dies; on a success, it becomes Clumsy 2, Drained 2, Doomed 2, and enfeebled 2 for 1 week; these conditions can't be removed or reduced by any means until the week has passed. A target's physical body remains in suspended animation for the duration of the ritual, but if it's destroyed, the creature dies and its astral form also vanishes. This ritual only projects a portion of the targets' consciousnesses onto the Astral Plane. To travel physically to the Astral Plane (to reach the Outer Planes, for example) requires spells such as interplanar teleport.\nCritical Success All targets are able to navigate independently in the Astral Plane. Each target's silver cord is stronger than usual, providing them a +4 circumstance bonus to its Fortitude save to avoid dying if its astral form dies.\n\nSuccess You successfully project the targets.\n\nFailure You fail to project the targets.\n\nCritical Failure The process of separating the targets' spirits from their bodies is complicated, and something goes catastrophically wrong. All casters become Doomed 1, are immediately reduced to 0 Hit Points, and begin dying","source":{"provider":"PAIZO","sourceId":"4Cntq9odgW6xMpAs","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bandits-doom","name":"Bandit's Doom","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"30 minutes"}},"targeting":{"range":{"kind":"NONE"},"target":"1 item of 2 Bulk or less","area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"8d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"You ward the target item against those who would steal it. When a creature attempts to take the target into its possession, it takes 8d8 mental damage and is doomed, depending on the result of its Will save. The spell then ends. You can choose up to 10 creatures when you cast this spell; if you do, those creatures can take the target item without triggering the ward. You can only have one bandit's doom active at a time. If you cast the spell again, the newer casting supersedes the older.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is Doomed 1.\n\nFailure The creature takes full damage and is Doomed 2.\n\nCritical Failure The creature takes double damage and is Doomed 3.\n\nHeightened (+2) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"N9KjnGyVMKgqKcCw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.banishment","name":"Banishment","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature that isn't on its home plane","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You send the target back to its home plane. The target must attempt a Will save. You can spend an extra action while Casting this Spell and add a cost to the spell to give the creature a –2 circumstance penalty to its save. The cost must be a specially gathered object that is anathema to the creature. This spell fails if you aren't on your home plane when you cast it.\n\nCritical Success The target resists being banished and you are Stunned 1.\n\nSuccess The target resists being banished.\n\nFailure The target is banished.\n\nCritical Failure The target is banished and can't return by any means to the plane it's banished from for 1 week.\n\nHeightened (9th) You can target up to 10 creatures. The extra cost affects targets to which it is anathema.","source":{"provider":"PAIZO","sourceId":"bay4AfSu2iIozNNW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.belittling-boast","name":"Belittling Boast","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["auditory","concentrate","emotion","fear","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You boast about your skills or combat prowess, bolstering your own abilities and belittling your opponents. Select one of the following to boast about: melee attack rolls, ranged attack rolls, spell attack rolls, or a single skill. Attempt an Intimidation check to all enemies within 30 feet. Each creature that becomes additionally takes a -1 circumstance penalty to the attack roll or skill you boasted about for 1 minute. If at least one creature becomes frightened, you gain a +1 status penalty to the attack roll or skill you boasted about for 1 minute.\n\nHeightened (8th) The bonus and penalty increase to 2.","source":{"provider":"PAIZO","sourceId":"qxJE2iSJwPFLZrcK","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.black-tentacles","name":"Black Tentacles","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["attack","concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20,"text":"20-foot burst adjacent to a flat surface"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 20-foot burst adjacent to a flat surface\nOily black tentacles rise up and attempt to capture creatures in the area. Make spell attack rolls against the Fortitude DC of each creature in the area. Any creature you succeed against is and takes 3d6 bludgeoning damage. Whenever a creature ends its turn in the area, the tentacles attempt to grab that creature if they haven't already, and they deal 1d6[bludgeoning] damage to any creature already Grabbed.\n\nThe tentacles' Escape DC is equal to your spell DC. A creature can attack a tentacle in an attempt to release its grip. Its AC is equal to your spell DC, and it is destroyed if it takes 12 or more damage. Even if destroyed, additional tentacles continue to grow in the area until the duration ends. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"2w4OpAGihn1JSHFD","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blackfingers-blades","name":"Blackfinger's Blades","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","poison"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"up to 4 weapons, each wielded by a separate willing creature within range","area":null},"duration":{"text":"up to 1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pray for swift and painful death to your enemies and find your and your allies' weapons blessed to deliver just that.\n\nThe target weapons are coated with with a DC equal to your spell DC.\n\nThe effects remain on a weapon for 1 minute or until the weapon deals damage, whichever comes first.","source":{"provider":"PAIZO","sourceId":"y5pzaNfb17CM1slC","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blazing-fissure","name":"Blazing Fissure","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","earth","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":120}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"4d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"6d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1d6"}},"counteraction":false,"ritual":null,"description":"A thin crack rips through the earth, erupting with magma, then swiftly seals up. Each creature along the line and on solid ground takes 4d6 bludgeoning damage and 6d6 fire damage with a Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage, and it falls .\n\nCritical Failure The target takes double damage, and it falls prone.\n\nHeightened (+1) The damage increases by 1d6 bludgeoning and 1d6 fire","source":{"provider":"PAIZO","sourceId":"OYOCWWefZPEfp8Nl","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.blessing-of-defiance","name":"Blessing of Defiance","kind":"SPELL","rank":5,"rarity":"COMMON","traits":[],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"varies","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Channeling forth the power to persevere in the face of adversity, you grant the target the means to deny danger and avoid dire harm. Choose one saving throw: Fortitude, Reflex, or Will. The target gets a +4 status bonus to that saving throw for 1 round. The potency and number of targets of this blessing depend on how many actions you spend when Casting the Spell.\n\n1 (somatic) The spell targets you or one willing ally within range.\n\n2 (verbal) The spell targets you or one willing ally within range. If you choose Fortitude, the target gains resistance 15 to poison. If you choose Reflex, the target gains a +15-foot status bonus to its Speeds. If you choose Will, the target gains resistance 15 to mental damage.\n\n3 (verbal) The spell targets you and all willing allies within 30 feet.","source":{"provider":"PAIZO","sourceId":"1b55SgYTV65JvmQd","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blind-eye","name":"Blind Eye","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You enchant a single object, preventing it from being used for magical observation. If you cast this spell on a non-magical item used to cast scrying spells, such as a spell component pouch or a spell focus, the item can't be used to cast the spell. If you cast blind eye on a magical item that can be activated to scry (such as a Crystal Ball or ), the item can't be activated for scrying effects. Magical items that are twice blind eye's spell rank or more aren't blocked this way.","source":{"provider":"PAIZO","sourceId":"pfFxj4NI5KwO119I","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blinding-bottle","name":"Blinding Bottle","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"MGQATTlJaLW0Hqom","formula":"3d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure an exploding glass container filled with a sight-stealing poison and hurl it across enemy lines. Upon impact, the bottle bursts and exposes all creatures in the area to the toxin within. Each creature in the area must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 3d6 poison damage.\n\nFailure The creature is afflicted with blinding poison at stage 1.\n\nCritical Failure The creature is afflicted with blinding poison at stage 2.\nBlinding Poison (incapacitation, poison) Level 9\n\nMaximum Duration 4 rounds\n\nStage 1 3d6[poison|traits:incapacitation,poison] damage and for 1 round (1 round)\n\nStage 2 4d6[poison|traits:incapacitation,poison] damage and blinded for 1 round (1 round)\n\nStage 3 5d6[poison|traits:incapacitation,poison] poison damage and blinded for 1 round (1 round)\n\nStage 4 6d6[poison|traits:incapacitation,poison] poison damage and blinded for 1 minute (1 round)\nPFS Note: The poison inflicted by this spell has the incapacitation trait, but the spell itself does not. This means that a creature which fails the save against the spell begins at stage 1 for the poison.","source":{"provider":"PAIZO","sourceId":"3ygqSJYWZM1UV76Z","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blinding-foam","name":"Blinding Foam","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["acid","attack","concentrate","incapacitation","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"NE5nfcJxF8gmPf1n","formula":"5d10","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false},{"id":"rt4oeXP3SqcClH6r","formula":"1d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You spray a colorful, caustic foam into the target's eyes, which clings to their face. Make a spell attack roll. If you hit, you deal 5d10 acid damage and 1d6 persistent acid damage, and the target is for the duration. The foam can be removed with 3 Interact actions, which ends the persistent acid damage. These Interact actions don't need to be consecutive. When the target's persistent acid damage ends, the spell automatically ends.\n\nHeightened (8th) The initial damage increases to 9d10, and the persistent acid damage increases to 2d6.","source":{"provider":"PAIZO","sourceId":"7uL4XhHpxZpgNJPh","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.blink-charge","name":"Blink Charge","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","force","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You propel yourself through the fabric of space to deal a blow carrying the momentum of your teleportation. You teleport to an empty space adjacent to a creature you can see within range, then make a Strike against the creature with a weapon you're wielding. The Strike deals damage, plus an extra 2d8 force damage, depending on the result of your Strike.\nCritical Success Double damage, plus after the Strike, you can teleport the target into an empty space up to 5 feet away from its current position. The new space must be on the ground if it started on the ground, in the air if it was flying, and so on.\n\nSuccess The Strike deals full damage.\n\nFailure The Strike deals no damage, but the target takes 1d8 force damage.\n\nCritical Failure The Strike deals no damage, and you take 1d8 force damage.\nHeightened (+2) The spell's range increases by 60 feet, and any force damage the spell deals is increased by 1d8 force.","source":{"provider":"PAIZO","sourceId":"TDaMnCtZ72uyYrz8","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blister","name":"Blister","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"7d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You point at a target in range, and its skin grows searing blisters filled with caustic fluid. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target grows one blister. You can spend a single action, which has the concentrate trait, to pop a blister. The target and each creature in a originating from the target takes 7d6 acid damage (basic Fortitude save). You choose the direction of the cone, which can't include the target. When no blisters are left, the spell ends.\n\nFailure As success, but the target grows two blisters.\n\nCritical Failure As success, but the target grows four blisters.\n\nHeightened (+1) The damage of a popped blister increases by 1d6.","source":{"provider":"PAIZO","sourceId":"59NR1hA2jPSgg2sW","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blood-feast","name":"Blood Feast","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["attack","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"12d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Your head splits vertically into an enormous maw, which feasts upon the target's blood, dealing 12d6 piercing damage, depending on your spell attack roll. After the spell, your head sews back together as if it had never split apart. You gain temporary Hit Points for 1 minute equal to half the piercing damage the target takes.\n\nIf you are a gug, increase the piercing damage by 2d6 and increase the Persistent Bleed Damage you deal on a critical hit by 1d8. This spell doesn't alter a gug's appearance.\nCritical Success The creature takes double damage and (@item.rank - 4)d8[bleed].\n\nSuccess The creature takes full damage.\n\nFailure You miss and the creature takes no damage.\nHeightened (+1) The piercing damage increases by 2d6, and the Persistent Bleed Damage on a critical increases by 1.","source":{"provider":"PAIZO","sourceId":"ES6FkwXXqYr4ujQH","book":"Pathfinder #154: Siege of the Dinosaurs","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blood-feasting-breath","name":"Blood-Feasting Breath","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","healing","manipulate","vitality","void"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"oqOPvqTwINsivfRH","formula":"5d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"oqOPvqTwINsivfRH":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area (continued) two 30-foot cones\nLike a vorpal dragon, you absorb life with an inhale and release it with an exhale. All living creatures in the first cone take 5d6 void damage with a basic Fortitude save. You and all living creatures in the second cone regain Hit Points equal to the greatest damage a single creature took from the first cone.\nHeightened (+1) The damage and healing increase by 1d6.","source":{"provider":"PAIZO","sourceId":"94eJHyFPNM1Z3TZp","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.boomerang-shot","name":"Boomerang Shot","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["attack","concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"100"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SPELL_ATTACK"},"damage":[{"id":"pHsjrtV8uQcnp7AC","formula":"7d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You launch a curved length of wood at a foe that arcs around objects and obstacles to strike from an unexpected direction. Make a spell attack roll against the target's AC. This attack ignores the target's condition and ignores all cover except greater cover. If you hit, the projectile deals 7d10 bludgeoning damage.\nHeightened (7th) The damage increases to 9d10.\n\nHeightened (9th) The damage increases to 12d10, and the attack ignores cover completely.","source":{"provider":"PAIZO","sourceId":"zPVJI8Jltt3ERkaU","book":"Pathfinder #203: Shepherd of Decay","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.bountiful-oasis","name":"Bountiful Oasis","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["water"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"3 drops of fresh water taken from a naturally occurring lake within 1,000 miles of the ritual site"},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Nature or Survival","secondaryCasters":1},"description":"You redirect the flow of underground lakes and other nearby sources of water to cause a lush natural spring to emerge from the ground. The water of the spring is a clean source of fresh water, perfect for drinking, farming, and supporting all forms of life. The spring purifies itself every morning at dawn, removing toxins and contaminants unless they're more than double the spring's rank.\n\nThe ritual creates a spring that's geographically appropriate to the terrain where the ritual is performed; for example, it creates a desert oasis in sandy, arid regions and a natural hot spring in a mountain range.\n\nCritical Success A small pond or oasis appears, fed by a natural spring that discharges enough pure drinking water to sustain a small settlement. The ground in a surrounding the spring bursts with life, invigorated by the spring's irrigation. A variety of regionally appropriate, fruit-bearing plants and other crops immediately take root and prosper.\n\nSuccess As critical success, but the oasis is a small pool that discharges enough pure drinking water to sustain roughly a dozen people, without any plants growing around the perimeter.\n\nFailure You're unable to redirect the flow of the water.\n\nCritical Failure You create a small pond of fetid and stagnant water that never dries, attracting disease-carrying insects and sickening creatures who partake of its waters.","source":{"provider":"PAIZO","sourceId":"SnBc7Gl5VormWzS1","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.breath-of-life","name":"Breath of Life","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","healing","vitality"],"traditions":["DIVINE"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"5d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"Trigger A living creature within range would die.\n\nYour blessing revives a creature at the moment of its death. You prevent the target from dying and restore 5d8 Hit Points to the target. You can't use breath of life if the triggering effect was a death effect or an effect that leaves no remains, such as\n\nHeightened (+2) The healing increases by 1d8.","source":{"provider":"PAIZO","sourceId":"Hnc7eGi7vyZenAIm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.call-spirit","name":"Call Spirit","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare candles and incense worth a total value of 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert) or Religion (expert)","secondaryChecks":"Occultism or Religion (whichever isn't used for the primary check)","secondaryCasters":1},"description":"You tear the veil to the afterlife and call a spirit from its final resting place. You must call the spirit by name, and you must provide a connection to the spirit, such as a possession, a garment, or a piece of its corpse. A spirit unwilling to heed your call can attempt a Will save to avoid it; on a critical success, a trickster spirit Impersonates the spirit you meant to call. The DC of the Will save is 2 lower if you haven't met the spirit in life. Either way, the spirit appears as a wispy form of the creature you meant to call. Each minute of the duration, you can ask the spirit a question. It can answer how it pleases or even refuse to answer. If the spirit isn't in the afterlife (such as if it's an undead), all results other than critical failures use the failure effect.\n\nCritical Success The spirit is particularly cooperative, and even if it has strong reasons to deceive you, it takes a -2 circumstance penalty to its Deception checks.\n\nSuccess You call the spirit.\n\nFailure You fail to call a spirit.\n\nCritical Failure One or more evil spirits appear and attack.","source":{"provider":"PAIZO","sourceId":"gsYEuWv04XTDxe91","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.celestial-brand","name":"Celestial Brand","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["curse","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 unholy creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d4","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1"}},"counteraction":false,"ritual":null,"description":"A blazing symbol appears on the target, cursing it to face divine justice. You and your allies receive a +1 status bonus to your attack rolls and skill checks against it.\n\nAnytime a holy creature damages it, the holy creature deals an additional 1d4 spirit damage. The target is then temporarily immune for 1 minute.\nHeightened (+2) The spirit damage increases by 1.","source":{"provider":"PAIZO","sourceId":"9WlTR9JlEcjRmGiD","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.chameleon-coat","name":"Chameleon Coat","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"up to 8 creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shift the colors of the targets' outermost layer of clothing and gear to be closer to their environment when they remain still. Creatures affected by the spell gain a +3 status bonus to Stealth checks to Hide. The changed color granted by the spell always shifts to match the environment, even if there are drastic changes. If any piece of gear or clothing affected by the spell is removed from a creature, the spell ends for that creature.\nHeightened (6th) If a creature affected by this spell rolls a critical failure on its Stealth check to within 30 feet of a creature that would spot it, it instead only fails its check, as the spell mildly hypnotizes the spotter.\n\nHeightened (8th) As 6th rank, and the status bonus is +4.","source":{"provider":"PAIZO","sourceId":"xPrbxyOEwy9QaPVn","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chromatic-wall","name":"Chromatic Wall","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"LINE","feet":60}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an opaque wall of light in a single vibrant color. The wall is straight and vertical, stretching 60 feet long and 30 feet high. If the wall would pass through a creature, the spell is lost. The wall sheds bright light for 20 feet on each side, and dim light for the next 20 feet. You can ignore the wall's effects.\n\nRoll [[/r 1d4]] to determine the color of the wall. Each color has a particular effect on items, effects, or creatures that attempt to pass through. Chromatic wall can't be counteracted normally; rather, each color is automatically counteracted when targeted by a specific spell, even if that spell's rank is lower than that of chromatic wall.\n\n- Red The wall destroys ranged weapon ammunition (such as arrows and crossbow bolts) that would pass through, and it deals 20[fire] damage to anyone passing through, with a reflex save. can counteract a red chromatic wall.\n\n- Orange The wall destroys thrown weapons that would pass through, and it deals 25[acid] damage to anyone passing through, with a reflex save. can counteract an orange chromatic wall.\n\n- Yellow The wall stops acid, cold, electricity, fire, force, sonic, vitality, and void effects from passing through, and it deals 30[electricity] damage to anyone passing through, with a reflex save. can counteract a yellow chromatic wall.\n\n- Green The wall stops toxins, gases, and breath weapons from passing through. It deals 10[poison] damage to anyone passing through and makes them Enfeebled 1 for 1 minute. A fortitude save reduces the damage and negates the Enfeebled condition on a success. can counteract a green chromatic wall.\n\nHeightened (7th) The spell's duration increases to 1 hour. Roll [[/r 1d8]] to determine the wall's color; the results for 5-8 are below. A 30[fire]{red}, 35[acid]{orange}, 40[electricity]{yellow}, or 20[poison]{green} wall deals an extra 10 damage.\n\n- Blue The wall stops auditory, petrification, sonic and visual effects from passing through, and creatures passing through are subject to the effects of . can counteract a blue chromatic wall.\n\n- Indigo The wall stops divination and mental effects from passing through, and those passing through are subject to the effects of . can counteract an indigo chromatic wall.\n\n- Violet The wall prevents spells from targeting the other side (area effects still cross as normal). Creatures passing through must succeed at a will save or they are Slowed 1 for 1 minute; on a critical failure, the creature is instead sent to another plane, with the effect of . can counteract a violet chromatic wall.\n\n- Reroll, and creatures that pass through the wall take a -2 circumstance penalty to their saves.","source":{"provider":"PAIZO","sourceId":"forsqeofEszBNtLq","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chthonian-wrath","name":"Chthonian Wrath","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false},{"id":"zvXU9ZdRVHSORUUn","formula":"4d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","zvXU9ZdRVHSORUUn":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You evoke the energy of a part of the Outer Rifts. The damage types of the spell (one energy and one physical) are based on the result of rolling on the table below. You deal 4d6 damage of each of the corresponding damage types to each creature in the cone (8d6 total damage).\nHeightened (+1) The damage for each type increases by 1d6\nChthonian Wrath\n[[/r 1D4]]RealmManifestationDamage and type\n1SkiesBolts and lightning and flying debrisBludgeoning and electricity\n2DepthsAcid and demonic shellsAcid and slashing\n3FrozenFrigid air and iceBludgeoning and cold\n4VolcanicJagged volcanic rocks and magmaFire and piercing","source":{"provider":"PAIZO","sourceId":"crF4g9jRN1y84MSD","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.cleansing-flames","name":"Cleansing Flames","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","healing","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You wrap the target in purifying flames. You can attempt to counteract a single poison or non-curse effect imparting the , , , , , , , or condition. The target can choose to empower the flames with their life force, becoming Drained 1 (or increasing their drained value by 1, if already under the condition) to grant you a +1 circumstance bonus to your counteract check.","source":{"provider":"PAIZO","sourceId":"tf4PMMMzR5xxJDun","book":"Pathfinder #168: King of the Mountain","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cloak-of-colors","name":"Cloak of Colors","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A cloak of swirling colors shrouds the target. Creatures are while adjacent to it, and attacking the target causes a brilliant flash of light. A creature that hits the target with a melee attack must attempt a Will save. The creature is then temporarily immune until the end of its turn; this effect has the incapacitation trait.\nSuccess The attacker is unaffected.\n\nFailure The attacker is for 1 round.\n\nCritical Failure The attacker is for 1 round","source":{"provider":"PAIZO","sourceId":"TCk2MDwf5L5OYjFC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cone-of-cold","name":"Cone of Cold","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"12d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Icy cold rushes forth from your hands. You deal 12d6 cold damage to creatures in the area.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"3puDanGfpEt6jK5k","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.confusing-cry","name":"Confusing Cry","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["auditory","concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You give an unsettling, warbling cry that causes nearby creatures to lash out without control. Each creature in the area that can hear must attempt a Will save.\n\nCritical Success The target is unaffected and immune to this spell for 1 minute.\n\nSuccess The target is Stunned 1.\n\nFailure The target is for 1 minute. It can attempt a new save at the end of each of its turns to end the confusion.\n\nCritical Failure As failure, and the creature immediately attacks itself. This Strike doesn't give the creature a flat check to recover from the confusion.","source":{"provider":"PAIZO","sourceId":"I7oklLZy4aTHIdc3","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.construct-mindscape","name":"Construct Mindscape","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["illusion"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"precious clay, wood, or other modeling materials worth spell rank × 20 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (master)","secondaryChecks":"Arcana or Occultism, Crafting","secondaryCasters":2},"description":"You create an entirely mental environment called an immersive mindscape. It can have any appearance you and the secondary casters imagine and hold in your minds as you execute the ritual. A mindscape is typically veiled, disguising its nature as a mental construct, but you can choose to make it overt. Even a veiled mindscape has some signs it's not a real place that can be revealed through close inspection or by spending a long time there. Most mindscapes are incapable of physically harming those inside. Even though the mindscape you create is limited in dimension, it appears to have a convincing environment around it, such as a sky and clouds.\n\nCritical Success You create a mindscape approximately a half-mile in length and width, and 50 feet in height (large enough to contain a typical village). The GM might allow you to make it larger if it has little detail, such as a grassy plain. You and any secondary casters of your choice can enter it and you can leave a doorway that you and any creatures you designate can pass through.\n\nSuccess As critical success, but the mindscape is approximately 25 feet in length, width, and height (like a modest house).\n\nFailure You can't hold the image together and it falls apart.\n\nCritical Failure Your secret desires horribly warp the mindscape into a distorted mirror of what you intended.\n\nHeightened (6th) The duration is 1 week.\n\nHeightened (9th) The duration is 1 year, and the area on a critical success is 1 mile in length and width.\n\nHeightened (10th) The duration is unlimited, and the area on a critical success is 1 mile in length and width. The cost increases to 2,000 gp.","source":{"provider":"PAIZO","sourceId":"Pp88ueeq4AlkaL6g","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.consuming-darkness","name":"Consuming Darkness","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","shadow","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"enemies in the area","area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your shadow wriggles before spreading out from you, forming a gateway of clinging, consuming shadow through which the horrors of another plane can barely be seen. The first time each turn you Sustain the Spell, the radius increases by 5 feet. Each enemy that enters the area or begins its turn in the area takes 2d6[void] damage and must attempt a Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature sinks partially into the shadow, taking half damage and a –5-foot circumstance penalty to its Speeds for as long it remains in the area.\n\nFailure As success, but the creature takes full damage and a 10-foot circumstance penalty.\n\nCritical Failure The creature is absorbed into the shadows, where it can be seen below the surface; it takes double damage and is for 1 round or until it Escapes.\n\nHeightened (+1) The damage increases by 1d6[void].","source":{"provider":"PAIZO","sourceId":"HMTloW1hvRFJ5Z2D","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.contagious-idea","name":"Contagious Idea","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","concentrate","emotion","manipulate","mental","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30 feet (see text)"},"target":"1 or 2 creatures other than yourself (see text)","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Nothing is so contagious as a thought. You place either a pleasant thought or a terrifying one in a creature's mind. You can then plant the same thought in a second creature's mind. You can't choose a creature that's already been a target of this casting of contagious idea, nor can you choose yourself. The second target can be beyond the range of the spell, but it must be within 30 feet of the first target.\n- Pleasant Thought The target is soothed by a pleasant memory, gaining 5 temporary Hit Points that last for 1 minute.\n- Terrifying Thought You plant a nameless unease in the target's mind. The target must attempt a Will save.\n- Critical Success The target is unaffected and is temporarily immune for 1 minute.\n- Success The target is Frightened 1 and is then temporarily immune for 1 minute.\n- Failure The target becomes Frightened 2.\n- Critical Failure The target becomes Frightened 3.\n\nHeightened (+1) The temporary Hit Points for a pleasant thought increase by 1.","source":{"provider":"PAIZO","sourceId":"Dby1eQ7y5dXBWlyc","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.control-water","name":"Control Water","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 50 feet long by 50 feet wide\nBy imposing your will upon the water, you can raise or lower the level of water in the chosen area by 10 feet. Creatures that have the water trait and that are in the area when you Cast the Spell must attempt a Fortitude save, with the effects of the spell.","source":{"provider":"PAIZO","sourceId":"zfn5RqAdF63neqpP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.corrosive-muck","name":"Corrosive Muck","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["acid","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"yNkEZ8qT669NMhzN","formula":"8d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area all squares in two {10-foot bursts}.\nYou create two puddles of acidic slime that hinders the movement of anyone who walks through them. The area of each pool becomes greater difficult terrain. Each round that a creature starts its turn in one of the pools or enters a pool during a move action it's using, it takes 8d6 acid damage with a basic Reflex save. A creature that critically fails its saving throw also takes 1d6[acid,persistent]. As normal, if a Large or larger creature starts its turn in both pools, it takes the damage only once.\nHeightened (+2) Create an additional 10-foot burst.","source":{"provider":"PAIZO","sourceId":"BlfOg9Ceymgjstjm","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.curse-of-death","name":"Curse of Death","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","curse","death","focus","hex","manipulate","void","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron wraps a hand around your target's heart. The target must attempt a Fortitude saving throw. Regardless of the result, the target is temporarily immune to all curses of death for 1 day.\nCritical Success The target is unaffected.\n\nSuccess The target is afflicted with the curse of death at stage 1, and the stage of the curse can't increase beyond stage 1.\n\nFailure The target is afflicted with the curse of death at stage 1.\n\nCritical Failure The target is afflicted with the curse of death at stage 2\nCurse of Death (curse, death, void) This curse ends when the spell ends\n\nStage 1 (max(4,(@item.rank)-1))d6[void] damage and (1 round)\n\nStage 2 (max(8,@item.rank+3))d6[void] damage and fatigued (1 round)\n\nStage 3 (max(12,@item.rank+7))d6[void] damage and fatigued (1 round)\n\nStage 4 death\nHeightened (+1) Increase the void damage taken on a success and during the first three stages of the curse by 1d6.","source":{"provider":"PAIZO","sourceId":"nQS4vPm5zprqkzFZ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dance-of-darkness","name":"Dance of Darkness","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","darkness","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"Varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You dance, Striding up to half your Speed. At either the start or end of your Stride, you create an area of magical darkness in a 10-foot burst centered on your location. This area is filled with magical darkness that works the same way as that created by a spell of the same rank. When you create the darkness, attempt a Performance check to dance, with a standard DC for your level, to determine the duration of the darkness.\n\nCritical Success 1 minute\n\nSuccess 2 rounds\n\nFailure 1 round","source":{"provider":"PAIZO","sourceId":"9BGEf9Sv5rgNBCk0","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dancing-blade","name":"Dancing Blade","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"mblrszws1jkc5f5f","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"mblrszws1jkc5f5f":"1d6"}},"counteraction":false,"ritual":null,"description":"You telekinetically animate a weapon that's unattended or on your person. It brandishes itself at a foe of your choice as if wielded by an invisible duelist. When you first Cast the Spell, the weapon automatically flies to the target and Strikes. It moves along with its target, always remaining within reach. Each time you Sustain the Spell, the weapon either Changes Partners or Strikes. The weapon's attacks use and contribute to your multiple attack penalty.\n- Change Partners Change the weapon's target to a different creature within 30 feet. The weapon flies to its new target.\n- Strike (attack) The weapon attacks its target using your spell attack modifier. On a hit, the weapon deals 3d6 damage, of a type determined by the weapon (if the weapon has the versatile trait or can otherwise deal multiple types of damage, you choose each time you attack).\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"ViqzVEprQVzCXZ9f","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.death-ward","name":"Death Ward","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature touched","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shield a creature from the ravages of void energy.\n\nIt receives a +4 status bonus to saves against death and void effects, gains void resistance 10, and suppresses the effects of the condition.","source":{"provider":"PAIZO","sourceId":"YvXKGlHOt7mdW2jZ","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.desperate-repair","name":"Desperate Repair","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 shield","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A shield within range would be reduced to 0 Hit Points by a damaging effect\n\nRequirements The triggering shield had more than 1 Hit Point before taking damage.\nYou hold a shield together with the power of your magic, forcing wood and steel to fuse back together. The shield remains at 1 Hit Point and isn't destroyed. Its construction is weakened until someone takes the time to repair it, preventing desperate repair or a similar ability from saving the same shield until your next daily preparations.","source":{"provider":"PAIZO","sourceId":"92JNBuY5pfFmywOd","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.diadem-of-divine-radiance","name":"Diadem of Divine Radiance","kind":"SPELL","rank":5,"rarity":"RARE","traits":["concentrate","light","manipulate","mythic","sanctified"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SPELL_ATTACK"},"damage":[{"id":"n6eXQAslPehKuaXl","formula":"4d8","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false},{"id":"rZgtouffoOBOPyXD","formula":"1d4","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"n6eXQAslPehKuaXl":"2d8","rZgtouffoOBOPyXD":"1d4"}},"counteraction":false,"ritual":null,"description":"You don a diadem of radiant light, which sheds bright light to a range of 60 feet and dim light to a further 60 feet. When you Cast the Spell and when you Sustain it during the duration, you can draw a disc of spiraling light from the diadem and throw it at a creature within 120 feet. Make a ranged spell attack at mythic proficiency against the target's AC. This action has the attack and spirit traits. On a hit, you deal 4d8 spirit damage, 1d4 persistent spirit damage, and the target is for 1 round (3 rounds on a critical hit). The persistent damage isn't doubled on a critical hit.\n\nIf the disc passes through an area of magical darkness or targets a creature affected by magical darkness, the disc's glow attempts to counteract the darkness using your Religion or Occultism skill modifier as the counteract check modifier and half your level as the counteract rank.\n\nHeightened (+2) The disc's spirit damage increases by 2d8, and the persistent damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"AWxS2lr86qNNQVDT","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.divine-dragons-watch","name":"Divine Dragon's Watch","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","contingency","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon an invisible divine draconic spirit to watch over your target. When the spell is complete, you gain the reaction; once you use the reaction, the spell ends.\nDragon's Protection R (concentrate, sanctified, spirit)\n\n@Embed[Compendium.pf2e.actionspf2e.Item.Zt9bo3FYLQihmpAz inline]\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"BBiO9ZdwyEJ581ES","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-immolation","name":"Divine Immolation","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"b9dAiWfV57lyCWpP","formula":"6d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"b9dAiWfV57lyCWpP":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Divine flames scour creatures within the area. Creatures take 6d6 fire damage and (@item.level -3)d6[persistent,fire] damage. The divine power within the flames scorches the spirit as well; a creature takes spirit damage instead of fire damage from divine immolation if that would be more detrimental to the creature (as determined by the GM).\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and no persistent damage.\n\nFailure The creature takes full damage and persistent damage.\n\nCritical Failure The creature takes double damage and double persistent damage.\n\nHeightened (+1) The damage increases by 1d6 and persistent damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"A16eFTRh82xIjMu8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.domoras-defense","name":"Domora's Defense","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"up to 3 creatures","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Domora Hume is considered by most to be the first god caller, conjuring a god from the Plane of Water named Dyzad to protect his town from Mammoth Lord raiders. A lost story of this defense claims that Dyzad appeared to be in three places at once, blocking the raiders' spears, swords, and torches. The intended lesson is that Dyzad will overcome any barrier to protect the people of Sarkoris. This spell gives that intention physical form, allowing the caster to protect their people.\n\nWhen you Cast this Spell, a watery replica of the eidolon Dyzad appears in front of each of the targets, granting them a +1 circumstance bonus to AC and fire resistance 5.\n\nWhile the replica persists, a target can use the Shield Block reaction with the replica. The replica has Hardness 15 (or Hardness 20 against fire damage). They can use this reaction to reduce damage from any spell or magical effect, even if it doesn't deal physical damage. After a target uses Shield Block, the replica dissipates. The spell ends when you no longer Sustain it or if all three replicas have dissipated, whichever happens first.","source":{"provider":"PAIZO","sourceId":"PIdXUPtE6ZGpFpXV","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dragon-wings","name":"Dragon Wings","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Leathery wings sprout from your back, giving you a fly Speed of 60 feet or your Speed, whichever is faster. If you're still flying when this spell's duration would end, you float to the ground, as with the effects of .\nHeightened (8th) The duration increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"HWJODX2zPg5cg34F","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.drain-planar-connection","name":"Drain Planar Connection","kind":"RITUAL","rank":5,"rarity":"UNIQUE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"six sets of rare herbs, each worth a total of 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 31 Nature (master)","secondaryChecks":"DC 26 Diplomacy or Nature or Occultism","secondaryCasters":5},"description":"You draw the planar energy from Idyllis, through the ley lines, and into the six latticework spheres.\n\nCritical Success You sever Idyllis's connection to the Plane of Wood permanently.\n\nSuccess You sever Idyllis's connection to the Plane of Wood for 10 years.\n\nFailure You sever Idyllis's connection to the Plane of Wood for 1 year, but the ritual backfires, dealing (4d12+26)[force] damage to all secondary casters (reflex save).\n\nCritical Failure The ritual backfires as a failure but doesn't sever Idyllis's connection.","source":{"provider":"PAIZO","sourceId":"Jte2jlX59a1yQPp8","book":"Pathfinder #202: Severed at the Root","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dread-ambience","name":"Dread Ambience","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["consecration","emotion","fear","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"2 days"},"cost":"candles, specialty salts, and rare herbs worth 80 gp total"},"targeting":{"range":{"kind":"NONE"},"target":"1 square mile","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Deception","secondaryCasters":1},"description":"In some places, it always feels like something is observing you, as if the very land doesn't want you there. Hostile creatures skitter about in the underbrush. Tendrils of mist try to lead you stray. Even the scent of the place is unwelcoming. Sometimes, this eerie atmosphere is a natural occurrence. Other times, it's the result of the dread ambience ritual.\n\nTo create this unwelcoming, intimidating aura, you must prepare the area with salts and herbs, traveling the entire edge of the area throughout the casting.\n\nAfter you complete your ritual, anyone who enters the area receives a status penalty to saving throws against fear effects within the dread ambience.\nCritical Success The sense of dread is particularly powerful. Every creature in an area takes a -2 status penalty to saving throws against fear effects.\n\nSuccess The dread ambience succeeds. Every creature in the area takes a -1 status penalty to saving throws against fear effects.\n\nFailure The dread ambience fails.\n\nCritical Failure The dread ambience fails, and the casters take a -1 status penalty to all Will saves for the next week.\n\nHeightened (7th) The dread ambience costs 750 gp and remains in place for 10 years.\n\nHeightened (9th) The dread ambience costs 5,000 gp and remains in place for an unlimited duration.","source":{"provider":"PAIZO","sourceId":"1QMjWGq1DPOQr4VL","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dreaming-potential","name":"Dreaming Potential","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing sleeping creature","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw the target into a lucid dream where it can explore the endless possibilities of its own potential within the everchanging backdrop of its dreamscape. If it sleeps the full 8 hours uninterrupted, when it wakes, it counts as having spent a day of downtime retraining, though it can't use dreaming potential for any retraining that would require either an instructor or specialized knowledge it can't access within the dream.","source":{"provider":"PAIZO","sourceId":"y0Vy7iNL3ET8K00C","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.drop-dead","name":"Drop Dead","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["illusion","manipulate","subtle","visual"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range is hit by an attack from an enemy.\n\nThe target appears to fall down dead, though it actually turns . Its illusory corpse remains where it fell, complete with a believable fatal wound. This illusion looks and feels like a dead body. If the target's death seems absurd—for instance, a barbarian at full health appears to be slain by 2 damage—the GM can grant the attacker an immediate perception check to disbelieve the illusion. If the target uses hostile actions, the spell ends. This ends the entire spell, so the illusory corpse disappears too.\nHeightened (7th) The spell doesn't end if the target uses a hostile action.","source":{"provider":"PAIZO","sourceId":"scTRIrTfXquVYHGw","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ectoplasmic-expulsion","name":"Ectoplasmic Expulsion","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon tendrils of ephemeral ectoplasm to pass through the target and carry away a harmful psychic affliction. You immediately attempt to counteract a single effect on the target with the emotion or possession trait, or an effect giving the target the or condition. If you fail to counteract the effect, you nevertheless set up a resonance that allows the target to more ably escape the effect on its own; for the next hour, the target gains a +2 status bonus to Will saves to shrug off the effect you failed to counteract (such as Will saves to shake off control by the spell).","source":{"provider":"PAIZO","sourceId":"PgDFDvX64eswapSS","book":"Pathfinder #165: Eyes of Empty Death","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-blast","name":"Elemental Blast","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30 feet (burst only)"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"8d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Area , , or\nYou gather elemental energy and blast your foes in one of the various listed shapes of your choosing, dealing 8d6 damage. This spell deals damage according to your elemental influence (for instance, slashing for air or fire for fire) and has your element's trait.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"Qlp8G3knwLGhAxQ0","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.elemental-breath","name":"Elemental Breath","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You open a miniature portal to an elemental plane within your mouth, then exhale a powerful explosion of the plane's element. Roll 1d6 to determine the element. If you used 3 actions to Cast this Spell, you can choose the element instead. This spell gains the trait matching the element.\n\nEach creature in the cone must attempt a basic Reflex save.\n\n- Air Strong winds and lightning strikes buffet creatures in the cone, dealing 6d10[electricity] damage. A creature that fails its save is also pushed 10 feet.\n\n- Earth A cone of mud deals 5d10[bludgeoning] damage to creatures in the area. A creature on the ground that fails its save slips and falls .\n\n- Fire A surging cone of fire deals 7d10[fire] damage.\n\n- Metal A cone of rust slices flesh and damages metal. Each creature in the area takes 5d10[slashing] damage. A creature made of metal gets a result one degree of success worse than it rolled, and an unattended metal object gets a critical failure.\n\n- Water A torrent of chilled water deals 3d10[cold] damage and 3d10[bludgeoning] damage.\n\n- Wood Branches rip through creatures, dealing 3d10[piercing] damage and 3d10[slashing] damage. Ground in the area becomes difficult terrain for 1 minute.\n\nHeightened (+1) The damage increases by [[/r 1d10]]. For water and wood, you can choose which damage type increases for each rank the spell is heightened.","source":{"provider":"PAIZO","sourceId":"fg5ZlSVXzGHNJfbO","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-form","name":"Elemental Form","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the power of the planes to transform into a Medium elemental battle form. When you Cast this Spell, choose a listed element. While in this form, you gain the corresponding trait and the elemental trait. You have hands in this battle form and can take manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n\n- AC = 19 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 10 temporary Hit Points.\n\n- Darkvision.\n\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +18, and your damage bonus is +9. These are Dexterity based (air, fire, or metal) or Strength based (earth, water, or wood). If your corresponding unarmed attack modifier is higher, you can use it instead.\n\n- Acrobatics (air, fire, or metal) or Athletics (earth, water, or wood) modifier of +20; ignore this change if your own modifier is higher.\n\nYou also gain specific abilities based on the type of elemental you choose:\n\n- Air\n\n- fly 80 feet, movement doesn't trigger reactions;\n\n- Melee 1 gust, Damage 1d4 bludgeoning.\n\n- Earth\n\n- Speed 20 feet, burrow 20 feet;\n\n- Melee 1 boulder, Damage 2d10 bludgeoning.\n\n- Fire\n\n- Speed 50 feet; fire resistance 10, weakness 5 to cold and 5 to water;\n\n- Melee 1 tendril, Damage 1d8 fire plus 1d4 persistent fire.\n\n- Metal\n\n- Speed 40 feet, fly 20 feet;\n\n- Melee 1 blade (versatile piercing), Damage 1d8 slashing plus 1d4 electricity.\n\n- Water\n\n- Speed 20 feet, swim 60 feet; fire resistance 5;\n\n- Melee 1 wave, Damage 1d12 bludgeoning, and you can spend an action immediately after a hit to push the target 5 feet with the effects of a successful .\n\n- Wood\n\n- Speed 20 feet, climb 30 feet;\n\n- Melee 1 branch, Damage 2d10 bludgeoning.\n\nHeightened (6th) Your battle form is Large and your attacks have 10-foot reach. You must have space to expand or the spell is lost. You instead gain AC = 22 + your level, 15 temporary HP, an attack modifier of +23, a damage bonus of +13, and Acrobatics or Athletics +23.\n\nHeightened (7th) Your battle form is Huge and your attacks have 15-foot reach. You must have space to expand or the spell is lost. You instead gain AC = 22 + your level, 20 temporary HP, an attack modifier of +25, a damage bonus of +11, double the number of damage dice (including persistent damage), and Acrobatics or Athletics +25.","source":{"provider":"PAIZO","sourceId":"1K6AYGisvo9gqdhs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-servitor","name":"Elemental Servitor","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare items and offerings worth a total value of 2 gp x the spell rank x the target's level, see text for more details"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Nature (expert)","secondaryChecks":"Diplomacy","secondaryCasters":2},"description":"You implore an elemental lord to send an elemental servitor of the lord's choice, with a level no greater than double the ritual's spell rank. The secondary casters explain what sort of assistance you need and why you need it; if the task is incredibly fitting to the elemental lord, the GM can grant a circumstance bonus to the secondary Diplomacy check or rule that the check is automatically a critical success. If you use the ritual without good reason, the result is automatically a critical failure.\n\nIf the ritual succeeds, you must offer the servitor payment depending on factors such as the duration and danger of the task. Payment always costs at least as much as a consumable item of the creature's level, and often costs as much as a permanent magic item of the creature's level to persuade a creature to fight alongside you. Your offerings should either align with the personal tastes of the elemental lord, or with the element—such as fresh flowers and bonsai plants for wood, or gemstones for earth.\n\nYou can alternatively name a being native to an elemental plane that you know personally, with the same level restriction. Such a creature might request something they personally want as payment, such as a favor or a game of chance.\n\nCritical Success Your elemental lord sends a servitor, and the servitor's payment costs only half as much as normal. If you ask for a particular elemental creature by name, your lord is likely to send them unless the creature is busy.\n\nSuccess Your elemental lord sends a servitor.\n\nFailure Your elemental lord does not send a servitor.\n\nCritical Failure Your elemental lord is offended and sends a sign of displeasure or possibly even an elemental creature to scold or attack you, depending on your lord's nature.","source":{"provider":"PAIZO","sourceId":"5NReCnDFFuThEAHB","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.engrave-memory","name":"Engrave Memory","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 stone of at least 1 Bulk","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You store memories inside a stone. This memory can convey up to 10 minutes of material. When you Cast this Spell, choose a command word. Doing so creates a carved symbol on the stone that hints at the word. Any creature can access the memories stored within the stone by using an action to speak the command word.\n\nAs it imparts the memories, the stone crumbles to dust, but the memory is infallibly available to the creature that activated the stone for the next 24 hours. After that time, the creature's normal capacity for memory must be relied upon to recall the stone's imparted memory. It's up to the GM what benefit the imparted memory grants, from circumstance bonuses to checks related to the memory or clear information on subjects the memory covers.","source":{"provider":"PAIZO","sourceId":"ddqmGnShyoRBKFkZ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entreat-thunderbird","name":"Entreat Thunderbird","kind":"RITUAL","rank":5,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare incense and offerings worth 300 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 29 Nature or Religion","secondaryChecks":"Diplomacy, Mountain Lore, Nature, or Survival","secondaryCasters":3},"description":"You entreat the thunderbird in the Tusk Mountains to come to your aid. While performing this ritual, the secondary casters can appeal to the thunderbird's pride or tempestuous nature to gain a +2 circumstance bonus to their checks.\nCritical Success The thunderbird is helpful to the casters for the duration.\n\nSuccess The thunderbird is friendly to the casters for the duration.\n\nFailure The thunderbird ignores the entreaty and remains indifferent.\n\nCritical Failure The thunderbird takes offense and permanently departs the area.","source":{"provider":"PAIZO","sourceId":"Do0pe0gn8OFdCOnN","book":"Pathfinder #209: Destroyer's Doom","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entwined-roots","name":"Entwined Roots","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"target":"Up to 5 willing living creatures","area":{"shape":"BURST","feet":20}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Slithering roots gird you and your allies in layers of flexible wooden protection. Each affected creature gains resistance 5 to bludgeoning and piercing damage. Whenever a creature protected by these roots is targeted by a ranged weapon attack but takes no damage (such as if the attack missed or the damage was reduced to 0 by resistance), the roots snatch up the ammunition or thrown weapon and hold it. The protected creature can retrieve the thrown weapon or ammunition as an Interact action.\n\nHeightened (7th) The resistances increase to 10.\n\nHeightened (9th) The resistances increase to 15.","source":{"provider":"PAIZO","sourceId":"VDK5cQ94BszDrMiJ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.establish-nexus","name":"Establish Nexus","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["consecration"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"magical foci worth 100 gp × the spell rank × the node's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 ley line node up to double establish nexus's level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana, Nature, Occultism, or Religion, matching the ley line's tradition (master)","secondaryChecks":"Ley Line Lore or Occultism","secondaryCasters":2},"description":"You focus the power of the node's intersecting ley lines into a powerful confluent point known as a ley line nexus. The ley line nexus grows out from the node in a 20-foot radius. The ley line nexus is more open and available for access to creatures you designate. When Tapping the Ley Line, these creatures get a degree of success one better than they rolled\n\nCritical Success The ley line nexus is established. The nexus is particularly powerful, allowing it to continually refresh its magical energy; thus, the nexus lasts for up to 100 years, unless the ley lines shift.\n\nSuccess The ley line nexus is established and lasts for a year and one day, unless the ley lines shift.\n\nFailure You fail to establish the ley line nexus.\n\nCritical Failure All casters take damage and suffer backlash effects as if they had critically failed to Tap every Ley Line in the node simultaneously, and they can't attempt to Tap those Ley Lines for a year and one day","source":{"provider":"PAIZO","sourceId":"1aXX52MnVbBvT9S7","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.establish-ward","name":"Establish Ward","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"},"areaFeet":5},"counteraction":false,"ritual":null,"description":"You bind a part of your essence to your surroundings, creating a warded area that grants you power within it, but drains you outside of it. While within the area, you can make nature's wrath Strikes by commanding plants, wind, rocks, and other natural features to attack enemies. These are melee Strikes that use your spell attack modifier, can target any creature within the ward, and deal 3d8 bludgeoning, piercing, or slashing damage.\n\nUpon Casting the Spell, you can immediately make a single nature's wrath Strike. You are while inside the ward, and can use the additional action only to make nature's wrath Strikes. You are Slowed 1 while outside the area.\nHeightened (+2) The area increases by 5 feet, and the Strikes deal an additional 1d8 damage.","source":{"provider":"PAIZO","sourceId":"XlQBVvlDWGrGlApl","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.etheric-shards","name":"Etheric Shards","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"u4xykvzyx1ej6xl4","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"u4xykvzyx1ej6xl4":"1"},"areaFeet":5},"counteraction":false,"ritual":null,"description":"You reach out and sow glittering splinters of force throughout the area, otherworldly caltrops of will and ectoplasm. The area is difficult terrain, even to flying or incorporeal creatures. Any creature that moves through the area takes 1d4 piercing damage per square traversed, with a basic Reflex save made at the end of each move action they take through the area.\nHeightened (+2) The spell's area increases by 5 feet, and the piercing damage increases by 1.","source":{"provider":"PAIZO","sourceId":"gasOL6a0WhOhUsgL","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.false-vision","name":"False Vision","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"BURST","feet":100}},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a false image that fools any attempts to scry on an area. Any scrying spell sees, hears, smells, and otherwise detects whatever you wish within the area, rather than what is actually in the area. You can Sustain the spell each round to change the illusion as you desire, including playing out a complex scene. If the scrying spell is of a higher rank than false vision, the scryer can attempt a Perception check to disbelieve the illusion, though even if they're successful, they can't learn what's truly going on in the area.","source":{"provider":"PAIZO","sourceId":"RCbLd7dfquHnuvrZ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.feast-of-supplication","name":"Feast of Supplication","kind":"RITUAL","rank":5,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"3 hours"},"cost":"25 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Cooking Lore, Crafting, Performance or Survival (expert)","secondaryChecks":"Deception or Thievery","secondaryCasters":2},"description":"When mortals attempt to sway gods, spirits, and other beings of great spiritual power to take sides in mortal affairs, those powers demand to be impressed. And what better way to impress than a cook-off? This old ritual has roots in the spiritadjudicated village festival contests of rural Tian Xia. Two or more rival parties must participate, performing the ritual simultaneously as assistants gather and prepare ingredients while each team's head chef does their best to create the ultimate dish to satisfy their patron's palate. Cheering bystanders are usually involved. While the primary caster—the chef—is always busy with cooking, it's very normal for the secondary caster assistants to spend most of their time interfering with the other teams and slowing them down.\nCritical Success You've truly blown your patron away with the competition and the meal you've expertly crafted. The supernatural patrons you sought to impress grant a request as if you'd received a critical success to Make a Request of them, even if they're indifferent or unfriendly to you. If there's some argument or confusion on what request should be granted, the patrons grant the request of the team that achieved the highest overall result. At the GM's discretion, the attitude of any patrons pleased by the ritual can permanently increase toward all participants in the ritual. In addition, the sheer theatricality and flair of your cooking has earned you deep respect and die-hard fans from the spectators, doubly so if you tied with another contender.\n\nSuccess You've created a wonderful meal that your patron loves. The supernatural patrons you sought to impress grant a request as if you'd received a success to Make a Request of them, even if they're indifferent to you. If there's some argument or confusion on what request should be granted, the patrons grant the request of the team that achieved the highest overall result. At the GM's discretion, the attitude of any patrons pleased by the ritual can permanently increase toward all participants in the ritual. All contestants have still earned the jovial respect and appreciation of the crowd for cooking something entertaining and lovely.\n\nFailure You've created a dish that doesn't impress. The winner of the competition is declared in the most unsatisfying and mechanical of manners—someone has to win, but no one is happy about it. The supernatural patrons you sought to impress politely make their excuses and leave as soon as they have a chance. At the GM's discretion, the attitude of any patrons who experienced the meal can permanently decrease toward all participants in the ritual.\n\nCritical Failure Your team's dish is ruined at the last possible moment in a spectacular manner. You completely embarrass yourself, and the attitude of the supernatural patrons who experienced this farce permanently decreases by one step toward you. If you haven't earned the ire of your patron host, you've definitely lost the respect of any onlookers or spectators.","source":{"provider":"PAIZO","sourceId":"bS3DW0MptpnZl5Zr","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fey-glamour","name":"Fey Glamour","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","illusion","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 10 creatures","area":{"shape":"BURST","feet":30,"text":"30-foot burst or Target"}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon fey glamours to cloak an area or the targets in illusion. This has the effect of either on the area or on the creatures, as if heightened to a rank 1 rank lower than fey glamour, using fey glamour's range and duration.","source":{"provider":"PAIZO","sourceId":"DdXKfIjDtORUtUvY","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fires-pathway","name":"Fire's Pathway","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","fire","manipulate","teleportation"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You step into a blazing fire that's big enough for you to fit inside and instantly teleport to any other fire within 5 miles that also has a sufficiently large size. Once you enter the first fire, you instantly know the rough locations of other sufficiently large fires within range and can exit from the original fire, if you prefer. You can't carry extradimensional spaces with you; if you attempt to do so, the spell fails.\n\nHeightened (6th) The fire you exit can be up to 50 miles away.\n\nHeightened (8th) The fire you exit can be up to 500 miles away.\n\nHeightened (9th) The fire you exit can be anywhere on the same planet.","source":{"provider":"PAIZO","sourceId":"nnYxDWU3Vzg9WenB","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flame-dancer","name":"Flame Dancer","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Fire encircles the target's hands and feet, and its eyes and hair catch ablaze. The target's unarmed Strikes deal an additional 2d6 fire damage. Critical hits with these Strikes also deal 2d4 persistent fire damage. Additionally, when the target attempts to a foe, they can use Performance instead of Intimidation; when using Performance to Demoralize, the action loses the auditory trait but gains the visual trait, and the target doesn't take a penalty when attempting to Demoralize a creature that doesn't understand its language.\n\nHeightened (7th) The fire damage increases to 3d6, and the persistent fire damage increases to 3d4. If the target gets a critical success on a Demoralize check using Performance, the target of the Demoralize check becomes from the target of flame dancer for 1 round.","source":{"provider":"PAIZO","sourceId":"p6ebe2PliRkGbmiV","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flame-strike","name":"Flame Strike","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":10,"text":"10-foot radius, 40-foot-tall cylinder"}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"8d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Area: 10-foot radius, 40-foot-tall cylinder\n\nYou call a rain of divine fire that plummets down from above, dealing 8d6 fire damage. Because the flame is infused with divine energy, creatures in the area apply only half their usual fire resistance. Creatures that are immune to fire, instead of gaining the usual benefit of immunity, treat the results of their saving throws as one degree of success better.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"E3X2RbzWHCdz7gsk","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.flames-of-ego","name":"Flames of Ego","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","incapacitation","light","manipulate","mental"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Elegant flames of incredible beauty coruscate across the target's body, creating overconfidence and carelessness. The target attempts a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target sheds bright light in a (and dim light to the next 40 feet) and becomes with itself for 1 round. It must spend at least 1 action on its turn on a taunting display of arrogance or overconfidence. Using actions that include such a display—such as using to show off—count toward this requirement.\n\nFailure As success, but the duration is 1 minute and the target can't act hostile toward a creature until that creature acts hostile toward the target.\n\nCritical Failure As failure, except the target must spend at least 2 actions on its turn on a taunting display of arrogance or overconfidence.","source":{"provider":"PAIZO","sourceId":"ZClfmMoKG3E926Uq","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flammable-fumes","name":"Flammable Fumes","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Sending magic deep underground, you conjure a cloud of toxic gases that swiftly degenerate into volatile fumes. The gases are invisible, requiring a successful Perception check against your spell DC to detect visually, though their acrid smell and toxic effects are clear once a creature has entered the cloud. A creature that enters the cloud or is within the cloud at the start of its turn takes 2d6 poison damage. A creature can take the poison damage from flammable fumes only once per round.\n\nOne round after you conjure the cloud, the gases loses stability and become flammable. If an open flame is brought into the cloud, or if anyone within the area uses a fire effect, the cloud detonates in a massive blaze that deals 10d6[fire] damage to all creatures within it with a reflex save, and the spell ends.\nHeightened (+2) The poison damage increases by 1d6 and the fire damage on an explosion increases by 2d6.","source":{"provider":"PAIZO","sourceId":"6AqH5SGchbdhOJxA","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.flowing-strike","name":"Flowing Strike","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A wave of flowing water rushes behind you like an elegant river, pushing you across the battlefield with fluid grace. You Stride up to 50 feet. This movement doesn't trigger reactions. You can make a Strike at any point during your Stride. If your Strike hits, the wave flows after you to batter the target of your Strike as well, dealing 2d10 bludgeoning damage and pushing it 10 feet in a direction of your choice.","source":{"provider":"PAIZO","sourceId":"zCLyETFoPqCQXLVy","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.footholds-and-foothills","name":"Footholds and Foothills","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"area that doesn't contain any structures","area":{"shape":"BURST","feet":30}},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{},"areaFeet":20},"counteraction":false,"ritual":{"primaryCheck":"Athletics (mythic) or Nature (mythic)","secondaryChecks":"Athletics, Acrobatics, Nature, or Survival","secondaryCasters":2},"description":"The physical world resists changes, but this can be subdued like any other foe. The hero-god of movement and mountains, the sure-footed Helidys, found the islands of Iblydos stubborn and unwilling to bend to his will. He asked a sandbar to lower itself so his ship could pass, but it refused. He asked again, and the sandbar told him to wait for the tides to change. On his third ask, he didn't wait for a response, and instead leapt from his ship and wrestled with it. The sandbar pushed and pulled with the currents, but Helidys succeeded and flattened the sandbar into a ribbon with his bare hands.\n\nWhen you cast this ritual, select to add, remove, roughen, or smooth out the area.\n\nAdd You create new terrain, selecting earth, stone, or water when you cast this ritual. Any creature within the newly created terrain's area moves to the closest available space. The new terrain can be created in a space that would not typically support it, such as a floating island.\n\nRemove You create a 30-foot-deep crater-like depression in the area. Unless otherwise specified, the terrain immediately beneath the destroyed area is the same type. Water flows into the crater if such is present along the area's circumference. Creatures standing on the destroyed terrain can attempt to if they are adjacent to a non-destroyed space. Otherwise, they use the typical rules for falling.\n\nRoughen You transform the area into difficult terrain. If the area was already difficult terrain, it becomes greater difficult terrain.\n\nSmooth You transform an area of difficult terrain into normal terrain, or an area of greater difficult terrain into difficult terrain.\nCritical Success You transform the area of your choice permanently.\n\nSuccess You transform the area for the ritual's duration.\n\nFailure You fail to transform the area.\n\nCritical Failure The ritual backfires, and now the land knows how to easily beat you. For the next week, the primary caster treats all instances of the terrain they attempted to manipulate as difficult terrain (or difficult terrain as greater difficult terrain).\nHeightened (+1) The area increases by 20 feet.","source":{"provider":"PAIZO","sourceId":"QGfVFyQhoalZbE9s","book":"Pathfinder #218: Titanbane","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forceful-hand","name":"Forceful Hand","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A Medium floating, disembodied hand made of magical force appears in an unoccupied space adjacent to you, following you across the battlefield to shield you against your foes' attacks. Each time you Sustain the Spell, the hand moves to an unoccupied space of your choice adjacent to you. When you Sustain the Spell, you can have the hand Fly to an unoccupied space of your choice adjacent to an ally to protect that ally instead. The hand's movement does not trigger reactions based on creature movement. The forceful hand occupies its space, but creatures can move through the hand freely.\n\nSuccessful attacks against the hand damage it, and damaging effects that can target a creature can target the hand. The hand has an AC of 25, 50 Hit Points, and can't recover HP by any means. A hit by a disintegrate spell or similar effect destroys the hand.\n\nThe hand's actions and the cover it provides depend on what actions you take during your turn. At the end of your turn, what the hand does is determined by the first entry on this list that matches a trait from any of the actions you used on your turn. For instance, if you Step, Stride, and Sustain the Spell, you use the entry for move actions, so the hand provides standard cover.\n- Manipulate or Attack The hand interposes between you and your foes. It provides lesser cover (+1 circumstance bonus to AC) against all attacks that pass through the hand's square.\n- Move The hand provides standard cover (+2 circumstance bonus to AC, Reflex, and Stealth checks) against all attacks that pass through the hand's square.\n- Concentrate The hand provides greater cover (+4 circumstance bonus to AC, Reflex, and Stealth checks) against all attacks that pass through the hand's square.\nHeightened (6th) The hand has AC 27 and 60 Hit Points. When you Cast this Spell, you can choose to replace the hand's Manipulate or Attack option with Swat.\n- Swat The hand Flies to an enemy of your choice within range and attempts to Push that enemy, using your spell attack roll instead of an Athletics check to determine the results of the Push.\nHeightened (7th) The hand has AC 30 and 70 Hit Points, and it is Large. When you Cast this Spell, you can choose to replace the hand's Manipulate or Attack option with Grasp or Swat.\n- Grasp The hand Flies to an enemy of your choice within range and attempts to Grapple that enemy, using your spell attack roll instead of an Athletics check to determine the results of the Grapple.\nHeightened (8th) The hand has AC 32 and 80 Hit Points, and it is Large. When you Cast this Spell, you can choose to replace the hand's Manipulate or Attack option with Grasp, Punch, or Swat.\n- Punch The hand Flies to an enemy of your choice within range and attempts to Strike that enemy with crushing force. The hand's Strikes use your melee spell attack modifiers and deal 7d8[force] damage. The hand's Strikes don't use or contribute to your multiple attack penalty.\nHeightened (9th) The hand has AC 35 and 90 Hit Points, and it is Large. When you Cast this Spell, you can choose to replace the hand's Manipulate or Attack option with Crush, Grasp, Punch, or Swat.\n- Crush If the hand doesn't have a target grabbed, it Flies to an enemy of your choice within range and attempts to Strike that enemy with deadly crushing force. The hand's Strikes are melee spell attacks that deal 6d8[force] damage. The hand's Strikes don't take or contribute to your multiple attack penalty. On a successful Strike, the target is grabbed by the hand until the end of your next turn, unless the hand moves or the target successfully Escapes against your spell DC. However, if the hand has a target grabbed when it uses Crush, it instead Constricts the target, dealing 6d8[force] damage with a basic Fortitude save.","source":{"provider":"PAIZO","sourceId":"rMGkk23qWvxTmgA8","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.foresee-the-path","name":"Foresee the Path","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","concentrate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 ally and 1 enemy","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"You see just a split second into the future and glean how an enemy will move, making it easier for your allies to strike it mid-action. Make a perception{Perception check} against the target enemy's Will DC or Deception DC, whichever is higher. The GM may judge a different DC is more appropriate if it's higher; for instance, using the Warfare Lore DC of a military captain. The target is then temporarily immune for 1 minute.\nCritical Success The target ally gains a reaction that lets it make a melee Strike against the target enemy, triggered if the enemy leaves a square within the ally's reach. If the ally already has an ability that lets it make melee Strikes as a reaction, such as Reactive Strike, the ally can forgo gaining the temporary reaction to instead gain a +2 status bonus to melee Strikes it makes as reactions.\n\nSuccess As critical success, but the status bonus an ally gets if it forgoes the reaction is +1.\n\nFailure The spell has no effect.","source":{"provider":"PAIZO","sourceId":"s4HTepjhQWV1yfBs","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fortifying-brew","name":"Fortifying Brew","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"high quality ingredients and brewing equipment worth 25 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting, Nature, or Society (expert)","secondaryChecks":"Alcohol Lore (or related lore), Crafting, Society","secondaryCasters":1},"description":"You craft a large quantity of restorative drink, such as an invigorating tea, a refreshing ale, or a stimulative alchemical tonic. The ritual speeds along any natural processes to make the brew, such as fermenting fruit to make a wine. At the conclusion of the first 3 hours of the ritual, you produce enough brew for up to 10 people to drink, any of whom can be the secondary caster of the ritual. The brew must then be consumed over the next hour. There is no danger of the drinkers becoming drunk if the brew is alcoholic. Once that hour is completed, you and the secondary caster attempt your checks as normal.\nCritical Success The brew is delicious and revitalizing. It casts a 4th-rank , a 4th-rank , and a 4th-rank on each drinker for each relevant affliction or condition, using your modifier for the primary skill check as the counteract modifier. Each drinker also gains 20 temporary Hit Points that last 12 hours and a +2 status bonus to saves against diseases and poisons for the next 12 hours.\n\nSuccess As critical success, except drinkers gain only 10 temporary Hit Points, and don't gain the status bonus to saves.\n\nFailure You and the other drinkers are left with a sour taste—something went wrong with the brewing process.\n\nCritical Failure Your attempt to craft the drink resulted in something more akin to a poison. You and the other drinkers become Sickened 4 and can't reduce the condition for 12 hours.\nHeightened (+1) The temporary Hit Points increases by 2 (or 4 on a critical success).","source":{"provider":"PAIZO","sourceId":"yRf59eFtZ50cGlem","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.freezing-rain","name":"Freezing Rain","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["cold","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"UKiopkMuk2wDUL6V","formula":"4d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"UKiopkMuk2wDUL6V":"1d6"}},"counteraction":false,"ritual":null,"description":"Intense cold rain comes from nowhere, a microcosm of a sudden downpour, and a magical tweak can turn the rain to freezing sleet. The driving rain and pooling water make the area difficult terrain and extinguish non-magical fires.\n\nOn subsequent rounds, the first time you Sustain the spell each round, you can move the area up to 20 feet and can also freeze the rain. If you freeze the rain, each creature in the area takes 4d6 cold damage and might be slowed, depending on result of its Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Slowed 1 for 1 round.\n\nCritical Failure The creature takes double damage and is Slowed 2 for 1 round.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"9AZEObUdLI2fwmPl","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.geyser","name":"Geyser","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"CYLINDER","feet":10}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1d6"}},"counteraction":false,"ritual":null,"description":"Area 10-foot radius, 50-foot-tall cylinder\n\nA powerful geyser blasts up from the ground, potentially pushing creatures on top of it into the air. The bottom of this spell's area must be on solid ground. Each creature in the area takes 3d6 bludgeoning damage and 4d6 fire damage, with a Reflex save. A creature pushed into the air by the geyser can't be pushed beyond the top of the geyser. After being pushed into the air, a creature falls unless it's flying or has some other means of staying aloft, taking falling damage (normally equal to half the distance it fell). After the geyser erupts, its area is filled with a cloud of steam for 1 round. All creatures in the steam are concealed, and all creatures outside the steam are concealed to creatures within it.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and isn't pushed into the air.\n\nFailure The creature takes full damage and is pushed 20 feet into the air. (10[bludgeoning|options:fall-damage] damage)\n\nCritical Failure The creature takes double damage and is pushed 40 feet into the air. (20[bludgeoning|options:fall-damage] damage)\n\nHeightened (+1) The damage increases by 1d6 bludgeoning and 1d6 fire.","source":{"provider":"PAIZO","sourceId":"i88Vi47PDDoP6gQv","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.glacial-heart","name":"Glacial Heart","kind":"SPELL","rank":5,"rarity":"RARE","traits":["concentrate","focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"10d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Ice and bone-deep cold assail the target, freezing it from the inside out. The frosty assault deals 10d6 cold damage, subject to the target's Fortitude save. After the effects are resolved, the target is temporarily immune for 1 day.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and is slowed 1 for 1 round. The spell ends.\n\nFailure The target takes full damage, is Slowed 1, and must attempt a Fortitude save at the end of each of its turns; this ongoing save has the incapacitation trait. On a failed save, the slowed condition increases by 1 (or 2 on a critical failure), to a maximum of slowed 4. On a success, the slowed condition decreases by 1. If at any point the slowed condition is reduced to 0, the spell ends.\n\nOnce a creature's actions are reduced to 0 by this slowed condition, the creature is completely encased in ice. It continues making saves against glacial heart, possibly allowing it to reduce its slowed condition enough that it can act. This ice has Hardness 4 and 8 Hit Points, and its DC to Force Open is your spell DC. Breaking the ice frees the creature and ends the spell. If someone other than the target breaks the ice from outside, the target is Stunned 1 and takes any damage dealt by the breaking effect in excess of the ice's Hit Points.\n\nCritical Failure As failure, but the target takes double damage and is initially Slowed 2.\n\nHeightened (+1) Increase the cold damage by 2d6.","source":{"provider":"PAIZO","sourceId":"ZyREiMaul0VhDYh3","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.glimmer-of-charm","name":"Glimmer of Charm","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["aura","concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You're bathed in a smooth, almost glittering aura that improves the attitude of those near you. Any creature that ends its turn in the aura must attempt a Will saving throw with the following effects. No matter the result, it's then temporarily immune for 24 hours. The effect lasts until the spell ends, even after the creature leaves the aura.\n\nCritical Success The creature is unaffected and is aware of the aura.\n\nSuccess The creature's attitude toward you improves by one step. If that improves its attitude to at least , it can't take hostile actions against you, though the effect ends as soon as you take a hostile action against the creature or its allies.\n\nFailure The creature's attitude toward you improves by two steps. It can't take hostile actions against you, though the effect ends as soon as you take a hostile action against the creature or its allies.\n\nCritical Failure The creature's attitude becomes to you, though the effect ends as soon as you take a hostile action against the creature or its allies. While the creature is helpful, it can't take hostile actions against you.","source":{"provider":"PAIZO","sourceId":"ftZ750SD2iIJKIy3","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gluttonous-growth","name":"Gluttonous Growth","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","plant","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"squares contain plants"},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"pwae34vzLdflGiXR","formula":"4d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"pwae34vzLdflGiXR":"2d6"}},"counteraction":false,"ritual":null,"description":"Plants in the area grow rapidly, taking on carnivorous characteristics as they seek to consume prey. All affected squares are difficult terrain, both on the ground and for flying creatures. Each creature that begins its turn in the area must attempt a Reflex save unless it's already or .\n\nWhen you Sustain this spell, each creature grabbed or restrained by the plants takes 4d6 piercing damage.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is grabbed until the beginning of its next turn or it Escapes.\n\nFailure The creature is grabbed until the spell ends or it Escapes.\n\nCritical Failure The creature is restrained until the spell ends or it Escapes.\n\nHeightened (+1) The damage dealt by the plants when you Sustain the spell increases by 2d6.","source":{"provider":"PAIZO","sourceId":"91ZbBll8M7IXQ4yw","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.grasping-grave","name":"Grasping Grave","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"6d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Hundreds of skeletal arms erupt from the ground in the area, clawing at creatures within and attempting to hold them in place. The skeletal arms deal 6d6 slashing damage. Each creature in the area must attempt a Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and a –10-foot circumstance penalty to its Speeds for 1 round.\n\nCritical Failure The creature takes double damage and is for 1 round or until it Escapes.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"2YIr0S2Gt14PMMQp","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.grisly-growths","name":"Grisly Growths","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 corporeal creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"10d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"This gruesome spell causes the target to grow excess limbs and organs, whether it be fingers multiplying until hands resemble bushes, eyes popping open in bizarre places, legs sprouting from the side of the body, or some other result. The target takes 10d6 piercing damage (basic Fortitude save) as the new features erupt. This spell has no effect on a target with a mutable anatomy or no limbs, such as an ooze or a protean. The growths rot rapidly and fall away after 1 round.\n\nIn addition, unless the initial target critically succeeds, creatures within 30 feet of the target, including the target, must attempt will saves, after which they're temporarily immune to this secondary effect of grisly growths for 1 hour. This additional effect is a mental and visual effect.\nSuccess The creature is unaffected.\n\nFailure The creature is Sickened 1.\n\nCritical Failure The creature is Sickened 2.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"d9sBzPOXX3KT8uTu","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hallucination","name":"Hallucination","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["illusion","incapacitation","manipulate","mental","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target consistently detects one thing as another, can't detect something that's there, or detects something that's not there, though it doesn't alter their beliefs. You choose which of these effects applies, and you determine the specifics of the hallucination. For example, you could make the target see all elves as humans, be unable to detect the presence of their brother, see their beloved good luck charm on their person even when it isn't, or see a tower in the center of town.\n\nThe target can attempt an initial Will save, with effects below. They also receive a Will save to disbelieve the hallucination every time they or directly interact with the hallucination. For example, the target could attempt to disbelieve the hallucination each time they interacted with an elf, bumped into their brother accidentally, tried to check their charm, or studied the tower. The target can attempt to disbelieve with a large circumstance bonus in situations determined by the GM, such as if the target attempted to climb the nonexistent tower.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature perceives what you chose until it disbelieves, but it knows what the hallucination is.\n\nFailure The creature perceives what you chose until it disbelieves.\n\nCritical Failure The creature perceives what you chose until it disbelieves, and it trusts its false senses, taking a -4 circumstance penalty to saves to disbelieve.\n\nHeightened (6th) Choose to either target up to 10 creatures or change the spell's duration to until your next daily preparations.\n\nHeightened (8th) Choose to either target any number of creatures or change the spell's duration to unlimited.","source":{"provider":"PAIZO","sourceId":"U58aQWJ47VrI36yP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.healing-well","name":"Healing Well","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"4d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"3"}},"counteraction":false,"ritual":null,"description":"You call forth a well of healing that you and your allies can draw from later. The well appears as a disc of shimmering light on the ground in a square within range. At any time during the duration, if you or an ally are adjacent to the well, that character can Interact to tap into the well's power, recovering 4d8 Hit Points. When the well has been tapped five times, the spell ends. The well is made of insubstantial energy, allowing creatures to move through it and even end their turn in its space.\n\nIf you use an ability that increases the amount of healing this spell grants, that increase applies only to the first time someone taps the well.\nHeightened (+1) The healing increases by 3.","source":{"provider":"PAIZO","sourceId":"CzjQtkRuRlzRvwzg","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hellfire-plume","name":"Hellfire Plume","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate","sorcerer","spirit"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"60 feet; 10-foot radius, 60-foot tall cylinder"},"area":{"shape":"CYLINDER","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"4d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1d6"}},"counteraction":false,"ritual":null,"description":"You call forth a plume of hellfire that erupts from below, dealing 4d6 fire damage and 4d6 spirit damage.\nHeightened (+1) The fire and spirit damage each increase by 1d6.","source":{"provider":"PAIZO","sourceId":"9LHr9SuDLTicdbXs","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.hologram-cage","name":"Hologram Cage","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","concentrate","illusion","light","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"CUBE","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Area 1 cube 20 feet on each side\nYou weave light into a cube of vivid and fantastic patterns. The walls shed bright light for 10 feet (and dim light for the next 20 feet) and completely block line of sight; creatures within the cage can't be seen by creatures outside of it, though they can see each other, and creatures outside of it can't see into it. You can the spell, and if you Cast the Spell again, your previous hologram cage ends.\nHeightened (7th) The range of the spell increases to 80 feet, and you can expand the cube to be 25 feet on each side.","source":{"provider":"PAIZO","sourceId":"wykbu2KW9tMBRySr","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.house-of-imaginary-walls","name":"House of Imaginary Walls","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","illusion","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You mime an 10-foot-by-10-foot wall adjacent to you and within your reach. The wall is solid to those creatures that don't disbelieve it, even incorporeal creatures. You and your allies can voluntarily believe the wall exists to continue to treat it as solid, for instance to climb onto it. A creature that disbelieves the illusion is temporarily immune to your house of imaginary walls for 1 minute. The wall doesn't block creatures that didn't see your visual performance, nor does it block objects. The wall has AC 10, Hardness equal to double the spell's rank, and HP equal to quadruple the spell's rank.","source":{"provider":"PAIZO","sourceId":"PEfSofHm73IT3Khc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.howling-blizzard","name":"Howling Blizzard","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["air","cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"2YlEXgT93lbWXENb","formula":"10d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"2YlEXgT93lbWXENb":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Freezing winds extend from your hands, pushing away from you with great force. If you Cast this Spell with 2 actions, it has an area of a 60-foot cone; if you Cast this Spell with 3 actions, it has a range of 500 feet and an area of a 30-foot burst. Each creature in the area takes 10d6 cold damage with a basic Reflex save. Snowdrifts and icy gales fill the area until the start of your next turn, making the area difficult terrain.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"xxWhyl81w3ckslAU","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hunters-vision","name":"Hunter's Vision","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 hunted prey","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your target glows with a magical aura visible only to you and those who follow your lead. Your target is visible to you and others sharing your benefits even if it wouldn't normally be due to lighting or the or conditions, though cover from opaque objects still blocks your sight. You ignore the flat check against the target due to the Concealed condition, and the target isn't automatically from you due to darkness or being Invisible.","source":{"provider":"PAIZO","sourceId":"tj86Rnq3QuQnDtG3","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.illusory-scene","name":"Illusory Scene","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate","olfactory","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You craft an imaginary scene that includes up to 10 discrete creatures or objects of various sizes, all of which must be within the spell's area. These elements generate appropriate sounds and smells, and they feel right to the touch. Elements of an illusory scene are incapable of speech. Unlike with the spell, creatures in your scene lack combat abilities and statistics. Your scene doesn't include changes to the environment around it, though you can place your scene within the illusory environment of a spell.\n\nWhen you create the scene, you can choose to have it be static or follow a program. Though a static scene is stationary, it includes basic natural movement. For example, wind blowing on an illusory piece of paper would rustle it. A program can be up to 1 minute long and repeats when finished. For instance, you could create a scene of two orcs fighting each other, and the fight would go the same way for each repetition. If you create a loop, the two fighters end up in the same place at the start of the scene and at the end of it, but you can smooth the program so it's hard to tell when the loop ends and begins. Anyone observing the scene for more than a few minutes almost always notices it looping. You're unable to alter the program after you create the illusion.\n\nAny creature that touches any part of the image or uses the action to examine it can attempt to disbelieve your illusion. If they interact with a portion of the illusion, they disbelieve only that portion. They disbelieve the entire scene only on a critical success.\n\nHeightened (6th) Creatures or objects in your scene can speak. You must speak the specific lines for each actor when creating your program. The spell disguises your voice for each actor.\n\nHeightened (8th) As the 6th-rank version, and the duration is unlimited.","source":{"provider":"PAIZO","sourceId":"Ucf8eynbZMfUucjE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.imaginary-lockbox","name":"Imaginary Lockbox","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 container and its contents, totaling 10 Bulk or less","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You turn a container and its contents into an imaginary form stored in your mind that only you can see and interact with. The container's physical properties—the material from which it's made, any locks, or other features—are irrelevant to the casting of this spell, but the container can't contain any creatures. The container has no Bulk, and you can visualize everything inside it.\n\nYou can retrieve an item from the lockbox as an activity that takes 3 actions and has the concentrate and manipulate traits. Putting items back isn't possible. You can Dismiss the spell. When the spell ends, the container returns to its normal state, either appearing in your hands if it can fit there or on the ground adjacent to you if not.","source":{"provider":"PAIZO","sourceId":"PERUlvKPtF7dMzN4","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.impaling-spike","name":"Impaling Spike","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"8d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You conjure a spike that thrusts up from the earth beneath a target creature, potentially impaling it. The spike is made of cold iron and deals 8d6 piercing damage. The target must attempt a Reflex save.\n\nCritical Success The target dodges the spike and is unaffected.\n\nSuccess The target is struck by the spike and takes half damage.\n\nFailure The target is impaled through a leg or another nonvital body part. The creature takes full damage and, if it's standing on solid ground, becomes . It can attempt to (the DC is your spell DC). While it remains impaled, it takes damage from any weakness to cold iron it has at the end of each of its turns.\n\nCritical Failure As failure, but the creature is impaled through a vital organ or its center of mass, taking double damage, and it is as long as it's impaled.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"oXeEbcUdgJGWHGEJ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.incarnate-ancestry","name":"Incarnate Ancestry","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["attack"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"7 days"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Arcana, Medicine, Occultism, or Religion","secondaryCasters":3},"description":"You attempt to reach back through time to make brief contact with one of the many past lives of the willing creature, then transform their current body to incarnate elements of that past life's ancestry into the present. At the GM's option, a creature might not have any past lives to draw from, in which case this ritual fails. A PC should always be able to make full use of this ritual if it's cast on them should the GM chooses to allow this ritual into their game.\n\nWhile incarnate ancestry can be cast anywhere, if cast in the vicinity of a site infused with energies conducive to reincarnation and contacting past lives (such as in area D7 of the Sanctum of the Cleansed), checks made to perform this ritual gain a +4 circumstance bonus.\n\nCritical Success You infuse the creature with elements from a previous incarnation. The character can reselect all ancestry feats, or even select an entirely new ancestry (choosing from those allowed by the GM). The newly incarnated ancestry must still fully support other character build options; you can't choose feats or ancestries that would invalidate class choices. The character is Clumsy 1 and Stupefied 1 for 10 minutes as they acclimate to their new body.\n\nSuccess As critical success, but the transformation is disorienting to the creature, who must come to terms with their new body and the strange echoes of memories from the past life that fade in time. The creature becomes clumsy 1 and stupefied 1 for one week; these conditions can't be removed or reduced by any means until the week has passed.\n\nFailure The attempt to incarnate ancestry is unsuccessful.\n\nCritical Failure As failure, but the attempt to transform leaves the creature feeling as if their own body were unfamiliar. They become clumsy 1 and stupefied 1 for one week; these conditions can't be removed or reduced by any means until the week has passed.","source":{"provider":"PAIZO","sourceId":"DcUGLLyaa9tHH1kN","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.incendiary-fog","name":"Incendiary Fog","kind":"SPELL","rank":5,"rarity":"RARE","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"goajz5243wuz07dx","formula":"10d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a cloud of flammable black dust. The cloud functions as . If any open flame or fire effect is within the spell's area when it's cast, or later enters or occurs within the area, the cloud ignites. Creatures in the cloud take 10d6[fire] damage (basic Reflex save), and the spell ends.","source":{"provider":"PAIZO","sourceId":"I2fwPslQth0DTPQD","book":"Pathfinder #177: Burning Tundra","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.inevitable-disaster","name":"Inevitable Disaster","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","curse","manipulate","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"55","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"10"}},"counteraction":false,"ritual":null,"description":"You briefly glimpse cause and effect, putting into motion a chain of events that will visit doom on your enemy at some point in the future, though you're not quite sure when or how the doom will occur. Some kind of strange accident occurs [[/gmr 1d4 #rounds]]{1d4 rounds} later, dealing 55 damage to the creature, with a basic Fortitude save. This happens regardless of where the target is located at the time, even if it travels to another plane. The GM should roll to determine when the damage occurs secretly and determine the form of the accident as well as the type of damage it deals; generally, the accident should be one that deals physical damage of some type (for instance, a tree branch might fall on the foe and deal bludgeoning damage, or a window might break and fling sharp slashing glass at them), though other damage types might be appropriate in more unusual environments.\n\nHeightened (+1) The damage increases by 10.","source":{"provider":"PAIZO","sourceId":"8THDHP0UC7SgOYYF","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.infectious-comedy","name":"Infectious Comedy","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tell a magical joke and infect a target with laughter that spreads to those nearby. The first time you Sustain the Spell each round, you can target another creature you can see that is within 30 feet of an affected target. The new target need not be able to see or hear the affected target, as the humor spreads magically. You can't target the same creature more than once with this spell.\n\nCritical Success The target is unaffected.\n\nSuccess The target begins giggling and can't use reactions.\n\nFailure The target is Slowed 1 and can't use reactions.\n\nCritical Failure The target falls and can't use actions or reactions for 1 round. It then suffers the failure effect.","source":{"provider":"PAIZO","sourceId":"SE3MddYAUyPKABuF","book":"Pathfinder #185: A Taste of Ashes","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.instant-minefield","name":"Instant Minefield","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["fire","illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"4cfdiUtP9KEfrhAS","formula":"3d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"ItwK3WaGOvx5tM06","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"4cfdiUtP9KEfrhAS":"1d6","ItwK3WaGOvx5tM06":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You create several hidden mines throughout the area that explode when stepped on. Choose up to 6 unoccupied squares within range. A mine appears in each chosen square, visible only to you and your allies. A mine can't be targeted and isn't affected by area effects, but if it hasn't been triggered by the end of the spell's duration, it dissipates harmlessly. A creature that can see creatures and objects can see the mines. A creature can also attempt a Perception check against your spell DC to [[/act seek]] to find an invisible mine.\n\nA creature who enters a square with an invisible mine triggers it, causing an explosion that deals 3d6 fire damage and 3d6 piercing damage (basic Reflex save) to the creature and every creature in a from the mine's square.\nHeightened (+1) The fire damage and piercing damage dealt by a mine each increase by 1d6.","source":{"provider":"PAIZO","sourceId":"vuehhQN8gPSpqcEK","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.invoke-spirits","name":"Invoke Spirits","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","emotion","fear","manipulate","mental","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d4","1":"1d4"}},"counteraction":false,"ritual":null,"description":"Ragged apparitions of the dead rise to stalk the living. They deal 2d4 mental damage and 2d4 void damage to each living creature in the area, with a basic Will save. Additionally, creatures that critically fail the save are Frightened 2 and are for 1 round.\n\nOn subsequent rounds, the first time you Sustain the Spell each round, you can move the area up to 30 feet within the range of the spell. Living creatures in the new area must attempt saves with the same effects as above, except that critically failing doesn't make them flee.\n\nHeightened (+2) The mental damage and void damage each increase by 1d4.","source":{"provider":"PAIZO","sourceId":"hghGRzOSzEl4UXdS","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.kings-castle","name":"King's Castle","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and a willing creature swap places. You appear in the target's former space, and the target appears in your former space. You and your target must each be able to fit in the new spaces within range; otherwise, the spell fails.","source":{"provider":"PAIZO","sourceId":"vM8oBYaEPgEXBimM","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lashuntas-life-bubble","name":"Lashunta's Life Bubble","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["air","concentrate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a replenishing protective bubble of fresh, temperate air around the target. The shell of air enables the target to breathe even underwater or in a vacuum, protects from severe cold and heat, and grants a +1 status bonus to the target's saves against inhaled dangers such as inhaled poisons and .\n\nHeightened (6th) The bubble lasts until your next preparation.\n\nHeightened (8th) The bubble lasts until your next preparation, protects against extreme cold and heat, and grants a +2 status bonus instead of +1.","source":{"provider":"PAIZO","sourceId":"8rAcQOvm0nFrqAUt","book":"Pathfinder Adventure Path: Gatewalkers","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.let-not-the-fallen-rest","name":"Let Not the Fallen Rest","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"xHErZZpDyJfbnLs7","formula":"4d10","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"xHErZZpDyJfbnLs7":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You exhort your fallen comrades to return to the battle. Each allied creature within the emanation whose value is 2 or less regains 4d10 Hit Points and can Stand as a free action, which doesn't provoke reactions.\nHeightened (+1) The amount of healing increases by 1d10.\nPFS Note: This spell affects unconscious allies with a dying value of 2 or less, in addition conscious allies with the dying 1 or 2 condition. Conscious characters are not considered to have the dying 0 condition and are unaffected.","source":{"provider":"PAIZO","sourceId":"USKnG2ZSzVs4xn85","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.lightning-storm","name":"Lightning Storm","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","electricity","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"You create a black, rumbling storm cloud and call down one lightning bolt within the spell's area. The bolt is a vertical line from the top of the storm cloud to the ground below, dealing 4d12 electricity damage to creatures in the line (basic Reflex save). On subsequent rounds, the first time you Sustain the Spell each round, you can call another lightning bolt within the area. If you Cast this Spell outdoors, you can create two non-overlapping clouds instead of one, though you can still call down only one bolt per turn.\n\nHeightened (+2) The damage of each bolt increases by 1d12.","source":{"provider":"PAIZO","sourceId":"JyT346VmGtRLsDnV","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.magic-passage","name":"Magic Passage","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a visible tunnel through the wall in the chosen area, replacing the area with empty space. If the wall is thicker than 10 feet, the tunnel ends 10 feet in. Even a small layer of metal in the wall prevents this spell from functioning. This spell doesn't reduce the integrity of the structure. When the spell ends, anyone inside the tunnel is shunted to the nearest exit.\n\nHeightened (7th) The tunnel can be up to 20 feet deep. The areas of the wall that contain your tunnel's entrance appear completely normal (unless viewed with truesight or a similar effect), despite the tunnel's existence. The tunnel's entrance functions as a solid wall, but you can specify a password or a trigger, allowing creatures to enter freely.","source":{"provider":"PAIZO","sourceId":"115Xp9E38CJENhNS","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantle-of-the-frozen-heart","name":"Mantle of the Frozen Heart","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["cold","concentrate","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in a mantle of frigid ice magic, and your skin and armor morph into cold blue ice. Freezing air emanates from your body, sending a chill down anyone's spine who draws too close and leaving a fine dusting of frost in your wake. Upon Casting this Spell, pick two of the options below. As a single action, which has the concentrate trait, you can change one of your chosen abilities to a different option from the list.\n- Chilling Ice The ice around your body thickens, melting off to protect you from heat while inuring you from the cold. You gain resistance 10 to cold.\n- Heart of Ice Your body temperature plummets to blistering cold. Any creature that touches you, or that hits you with a melee unarmed attack or non-reach melee weapon attack, takes 2d6[cold] damage.\n- Ice Glide Ice trails from your feet for an instant as you move, allowing you to skate rapidly along the ice. You don't need to Balance on ice, and you ignore difficult terrain caused by ice or snow. While moving along a smooth surface, you gain a +20-foot status bonus to your land Speed.\n- Icy Claws Your hands morph into vicious, piercing claws of ice useful for attacking or climbing. As long as you have both hands free, you gain a climb Speed equal to your land Speed. You gain a claw unarmed attack with the agile and finesse traits, in the brawling weapon group. Your claw attack deals 1d6 piercing damage as its base damage, plus an additional 2d6 cold damage.","source":{"provider":"PAIZO","sourceId":"CcXtbTxtdV9MKQfu","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantle-of-the-magma-heart","name":"Mantle of the Magma Heart","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","fire","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in a mantle of blazing fire magic, and your skin and anything you're wearing morphs into burning hot lava. The air around you swelters with heat, and tiny sparks of flame dance behind you as you pass. Upon casting this spell, pick two of the options below. As a single action, which has the concentrate trait, you can change one of your chosen abilities to a different option from the list.\n- Enlarging Eruption You erupt in lava, which clings to you and hardens, causing your body to swell and burst until you grow to size Large. You're clumsy 1. Your reach increases by 5 feet (or by 10 feet if you started out Tiny), and you gain a +2 status bonus to melee damage. You can't choose this option if you're already Large or larger.\n- Fiery Grasp Your hands swell and grow with lava. You gain a lava fist unarmed attack in the brawling weapon group. Your lava fists deal 1d8 bludgeoning damage as their base damage, plus an additional 2d6 fire damage and 1d6 persistent fire damage.\n- Heart of Fire Your body's temperature becomes so hot that any creature that touches you, or that hits you with a melee unarmed attack or non-reach melee weapon attack, takes 2d6[fire] damage.\n- Warming Flames Flames flicker around you, warming away the cold while protecting you from the heat. You gain resistance 5 to cold and fire.","source":{"provider":"PAIZO","sourceId":"j2kfNBFpLa0JjVr8","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantle-of-the-melting-heart","name":"Mantle of the Melting Heart","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","metal","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bathe yourself in a mantle of liquid metal, gilding your skin and armor with an oily sheen. Upon Casting this Spell, pick two of the options below. As a single action, which has the concentrate trait, you can change one of your chosen abilities to a different option from the list.\n- Copper Core You draw electricity toward you, then disperse it. You gain resistance 10 to electricity. All electricity effects within 30 feet of you must succeed at a counteract check against your spell DC or target you and only you.\n- Golden Flesh Your body gains the chemical inertness of gold, barely reacting to substances that would otherwise greatly disturb your physiology. You become immune to poison and disease and gain a +2 circumstance bonus to your checks against any poison and disease effects currently affecting you.\n- Reactive Touch Your touch reacts easily with other metals. Any metal that touches you or that you touch takes 2d6[acid] damage that bypasses Hardness.\n- Weighted Grasp Your arms become long cables, your fists heavy as anchors. You gain a cabled fist unarmed attack with the disarm, finesse, reach, and trip traits and that's in the flail group. Your cabled fist deals 1d4 bludgeoning damage plus an additional 1d6 poison damage and Grab.","source":{"provider":"PAIZO","sourceId":"UcS6Tw9OuOAEDfzg","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mantle-of-the-unwavering-heart","name":"Mantle of the Unwavering Heart","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","morph","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Vines and branches envelop you in an instant, growing a wild bloom of colors that open to reveal your new form. Upon Casting this Spell, pick two of the options below. As a single action, which has the concentrate trait, you can change one of your chosen abilities to a different option from the list.\n\n- Evergreen Vitality You gain fast healing 3 and a +2 bonus to saves against poison and disease. This effect has the healing and vitality traits.\n\n- Overwhelming Perfume (aura, olfactory) A cloud of potent floral scent surrounds you in a . Creatures in the aura can't benefit from the scent ability and are Sickened 1 as long as they remain in the aura. The sickness is a disease effect.\n\n- Towering Trunk You grow to a considerable height. Increase your size to Large. You're Clumsy 1. Your reach increases by 5 feet (or by 10 feet if you started out Tiny), and you gain a grasping branch unarmed attack; this attack is in the brawling weapon group and deals 2d8[bludgeoning] damage plus Grab.\n\n- Unyielding Will Your mind becomes incredibly resilient to change. You're immune to being , and you get a +1 bonus to saves and DCs against mental effects.","source":{"provider":"PAIZO","sourceId":"3526YUgCvB5ZsKuX","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mariners-curse","name":"Mariner's Curse","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You afflict the target with the curse of the roiling, unforgiving sea. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes Sickened 1. Reducing its sickened condition to 0 ends the curse.\n\nFailure The target becomes sickened 1 and can't reduce its sickened condition below 1 while the curse remains. The curse can be lifted by 4th-rank or similar magic. Whenever the target is sickened and on the water at least a mile from shore, it is also Slowed 1.\n\nCritical Failure As failure, but the target becomes Sickened 2.","source":{"provider":"PAIZO","sourceId":"z2mfh3oPnfYqXflY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mind-probe","name":"Mind Probe","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cast your thoughts through a creature's mind, sifting for information. You access the target's memories and knowledge unless it fends you off with a Will save.\n\nSuccess The target is unaffected.\n\nFailure Each round of the spell's duration, you can Sustain the spell to ask a different question and attempt to uncover the answer. For each question, the target can attempt a Deception check against your spell DC; if the target succeeds, you don't learn the answer, and on a critical success, the target gives you a false answer that you believe is truthful Once you've asked the target a given question, asking it again, even with a separate casting of mind probe, produces the same result.\n\nCritical Failure As failure, and the target takes a –4 circumstance penalty to Deception checks against your questions.","source":{"provider":"PAIZO","sourceId":"9BnhadUO8FMLmeZ3","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mind-swap","name":"Mind Swap","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["mental","possession"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a pair of jeweled mirrors worth a total value of 50 gp × the level of the highest-level target"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"2 creatures of the same ancestry, of up to twice the rank of mind swap","area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Medicine or Occultism","secondaryCasters":1},"description":"This ritual allows two subjects to exchange minds, fully inhabiting one another's bodies. The two targets can be chosen from you, the secondary caster, or unrelated third parties present throughout the ritual. Normally, both targets must be of the same ancestry for the minds to be fully compatible, but at the GM's discretion, for a much higher cost, the targets can be from different ancestries; this requires much more adjudication of ancestry feats and abilities. When both targets are of the same ancestry, muscle memory and the influence of their soul allow them to carry over all their mechanical abilities into each new body, except they use the other body's heritage (and lineage, if any). The GM might rule that similar physiological changes can't be overridden with a mind swap.\n\nIf a body dies, the mind and spirit controlling it dies instantly. When the spell ends, the minds and souls snap back to their original bodies. At this time, if the original body is dead, the mind and soul attempting to return to that body die as well.\n\nCritical Success Each target's mind and spirit possess the other's body and can control it normally. The mind swap is unusually smooth, and the targets gain a +4 circumstance bonus to Deception checks to Impersonate each other.\n\nSuccess Each target's mind and spirit possess the other's body and can control it normally.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual is scrambled, sending a welter of memories into the target's minds. You and the secondary casters are Stupefied 2 for the next week.\n\nHeightened (9th) You can cast the ritual without a duration, leaving no magic to counteract. The effects are reversible only by another mind swap ritual or powerful magic like wish. This increases the cost of the ritual to 10,000 gp and is an evil act unless both targets are willing.","source":{"provider":"PAIZO","sourceId":"RWwiFnjxoJXn7H6D","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mirecloak","name":"Mirecloak","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 4 creatures","area":null},"duration":{"text":"up to 1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"b8s5znrsrnbdwuie","formula":"2d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap the targeted creatures in thin, sickly green shrouds that sap information from attackers. The shroud settles about each target's shoulders, granting a +1 status bonus to AC and a +2 status bonus to Stealth checks, both only while the target is in dim light or darkness.\n\nIf a creature deals damage in melee to or touches a cloaked creature, the cloak wraps around the attacker, temporarily connecting the psyches of the cloaked creature and the attacker and violently prying a random piece of interesting information from the attacker's mind. The attacker takes 2d8 mental damage and must attempt a Will save.\n\nAfterward, the spell ends for the cloaked creature, and the attacker is temporarily immune to mirecloak for 24 hours.\n\nCritical Success The attacker is unaffected.\n\nSuccess The attacker takes half damage.\n\nFailure The attacker takes full damage and is Sickened 1. In addition, the cloaked creature gleans a piece of information from the attacker's mind. The details and extent of this information are at the GM's discretion.\n\nCritical Failure As failure, but the attacker takes double damage and is Sickened 2.","source":{"provider":"PAIZO","sourceId":"NIop4eI2i7cKFGad","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mirror-malefactors","name":"Mirror Malefactors","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental","visual"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"7d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You completely surround a Large or smaller creature in a shimmering ring of illusory mirrors that follows it as it moves, even when the creature moves outside the range of the spell. These mirrors reflect the target, though if the target has no reflection, like a vampire, it's unaffected by mirror malefactors. As long as the target is surrounded by mirrors, it's Frightened 1, and it can't reduce its frightened value.\n\nWhen you Cast the Spell, the reflections leap from the mirrors and attack the target, dealing 7d8 mental damage with a basic Will save. On subsequent turns, this effect repeats the first time you Sustain the spell that turn. If the target succeeds at any Will save it attempts against mirror malefactors, the illusory mirrors shatter and the spell ends.\n\nHeightened (+1) The damage for both the initial effect and on subsequent turns increases by 1d8.","source":{"provider":"PAIZO","sourceId":"CmZCq4htcZ6W0TKk","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.moon-frenzy","name":"Moon Frenzy","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","morph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 5 willing creatures","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A feral aspect overcomes the targets, filling them with strength and ferocity. Targets gain 5 temporary Hit Points, a +10-foot status bonus to their Speeds, and weakness 5 to silver. They also grow vicious fangs and claws, which are unarmed attacks. The fangs deal 2d8 piercing damage; the claws deal 2d6 slashing damage and have the agile and finesse traits. The targets use their highest weapon or unarmed attack proficiency with these attacks, and if they have weapon specialization or greater weapon specialization, they add this damage as well. On a critical hit with one of these unarmed attacks, the creature struck takes 1d4 persistent bleed damage.\n\nThe targets can't use concentrate actions unless those actions also have the rage trait, with the exception of . A creature can attempt to end the spell's effect on itself by using a single action, which has the rage trait, to attempt a Will save against your spell DC; on a success, it ends the spell's effect on itself.\n\nIf a target is in the light of a full moon, it also grows by one size if it were Medium or smaller. This increases the reach of a Medium or Tiny creature by 5 feet.\n\nHeightened (6th) The temporary Hit Points increase to 10, the silver weakness to 10, and the damage dealt by the attacks to three dice.\n\nHeightened (10th) The temporary Hit Points increase to 20, the silver weakness to 20, and the damage dealt by the attacks to four dice.","source":{"provider":"PAIZO","sourceId":"YtesyvfAIwXOqISq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mosquito-blight","name":"Mosquito Blight","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["disease"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"amber and rare incense worth 750 gp"},"targeting":{"range":{"kind":"TEXT","text":"1-mile-radius circle centered on you"},"area":null},"duration":{"text":"5 days","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert; you must be the Mosquito Witch)","secondaryCasters":0},"description":"You infest the area with tenacious, biting insects that disease and drain life from creatures in the area. Arthropods (insects, spiders, and similar invertebrates) are unaffected and instead gain a +1 status bonus to attack rolls, skill checks, saving throws, and Perception checks while within the area. All other creatures are harassed by insects and exposed to the disease witch's hunger when they enter the area and once per day thereafter that they remain in the area. As part of casting this ritual, you create a Tiny ritual insect hive (Hardness 5, 10 HP) that must remain in the ritual's area. If the hive is removed or destroyed, the ritual's effect ends 1 hour later.\n\nWitch's Hunger (disease)\n\nSaving Throw Fortitude\n\nOnset [[/r 1d6 #hours]]{1d6 hours}\n\nStage 1 Enfeebled 1 (1 day)\n\nStage 2 Enfeebled 2 (1 day)\n\nStage 3 enfeebled 2 and Slowed 1 (1 day)\n\nStage 4\n\nStage 5 death\n\nCritical Success As success, and the disease is especially deadly, with Stage 3 instead causing unconsciousness and Stage 4 instead causing death.\n\nSuccess You create the ritual hive and cast the ritual.\n\nFailure You fail to cast the ritual.\n\nCritical Failure You fail to cast the ritual and instead cause ravenous insects to torment you, immediately exposing you to the witch's hunger disease.","source":{"provider":"PAIZO","sourceId":"dNpIc5k1aCI3bHIg","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mothers-blessing","name":"Mother's Blessing","kind":"RITUAL","rank":5,"rarity":"RARE","traits":["beast","consecration","vitality"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"at least 1 gallon of clean river water"},"targeting":{"range":{"kind":"NONE"},"target":"Ulgrem-Axaan's eggs","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Crafting, Medicine, Survival","secondaryCasters":3},"description":"You attempt to purify and stabilize the life inside of Ulgrem-Axaan's last remaining clutch of eggs. With its blessing, you wash the eggs clean from the filth of undeath and bury them in warm sand by the banks of a river in Garund.\n\nCritical Success The ritual is successful and the eggs hatch, giving life to an ancient species brought to the brink of extinction by the destruction of their home.\n\nSuccess As critical success, but only half of the eggs hatch (rounded up). You can try again with the remaining eggs.\n\nFailure No effect, and you must wait a week to try again.\n\nCritical Failure 90% of the eggs shatter (rounded up). You must wait a month to try again.","source":{"provider":"PAIZO","sourceId":"qVXraYXlTjissCaG","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.natures-pathway","name":"Nature's Pathway","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental","plant","teleportation"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You step into a living tree with a trunk big enough for you to fit inside it and instantly teleport to any tree within 5 miles that also has a sufficiently large trunk. Once you enter the first tree, you instantly know the rough locations of other sufficiently large trees within range and can exit from the original tree, if you prefer. You can't carry extradimensional spaces with you; if you attempt to do so, the spell fails.\n\nHeightened (6th) The tree you exit can be up to 50 miles away.\n\nHeightened (8th) The tree you exit can be up to 500 miles away.\n\nHeightened (9th) The tree you exit can be anywhere on the same planet.","source":{"provider":"PAIZO","sourceId":"F1qxaqsEItmBura2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.oblivious-expulsion","name":"Oblivious Expulsion","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"incense worth a total value of 150 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (master) or Religion (master)","secondaryChecks":"Deception, Society","secondaryCasters":2},"description":"Severing ties with a member of a cult courts danger and threatens to undermine the secrecy of the group, whether that secrecy protects its worshippers or enables them to operate in the shadows. Many cults end their association with a wayward member on the edge of a blade, but there are options that preserve both secrecy and the life of the expelled member. An oblivious expulsion removes knowledge of the cult but is time-consuming enough that a cult usually reserves it for only the most well-regarded members who nevertheless need to be removed-or for sleeper agents the cult wishes to place among society and activate later.\n\nIt's difficult to cast this ritual unless the target is willing or . If the creature is unwilling to accept the ritual, it can attempt a Will save to negate the effect. The effects of the ritual depend on the results of your Occultism check.\nCritical Success The ritual removes all memories of the cult's activity, practices, and secrets from the target's memory. The target remembers only what an average citizen of the larger society would know, which is typically nothing or a few rumors with very little detail. The spell is hard to detect: a spell or similar effect must be a higher rank than oblivious expulsion to detect it. You can Dismiss the spell. While casting the spell, you can choose to give the secondary casters the ability to Dismiss it. You can also choose to set a key phrase or event that causes the spell to be Dismissed. When the target witnesses this phrase or event, the spell immediately ends.\n\nSuccess As critical success, except the spell isn't harder to detect with detect magic.\n\nFailure The ritual fails.\n\nCritical Failure The ritual fails, and the target is temporarily immune for 1 month.","source":{"provider":"PAIZO","sourceId":"QIjc7Zyej0P3b9v5","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ode-to-ouroboros","name":"Ode to Ouroboros","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature's dying condition would reach the value at which they would die.\n\nYour ode staves off death. The target's dying condition remains 1 below the value at which it dies. This doesn't help prevent death from effects that kill the target without increasing its dying condition, such as and death effects.","source":{"provider":"PAIZO","sourceId":"DgCS456mXKw97vNy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.over-the-coals","name":"Over the Coals","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","manipulate","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You accuse the target of breaking its word to you and invoke the wrath of your patron to claim what's due, demanding the target pay you in currency, fulfill an order, or stand down. The demand can't be obviously self-destructive, or the spell fails. If the target resists, you take your payment from its life force. The target must attempt a Will save. Regardless of the result of its save, the target is temporarily immune for 1 day.\nCritical Success The target is unaffected and is immune to your pact broker cantrips for 1 day.\n\nSuccess If the target doesn't comply with your request by the end of its next turn, it takes 3d8[persistent,void] damage. If it later complies, the spell automatically ends.\n\nFailure As success, but if the target doesn't comply, it is Drained 1 and takes 6d8[persistent,void] damage.\n\nCritical Failure As success, but if the target doesn't comply, it is Drained 2 and Doomed 1, and takes 6d8[persistent,void] damage. Even if the target completes your commands later, the spell doesn't end until all the conditions end.\nHeightened (9th) You can target up to two creatures.","source":{"provider":"PAIZO","sourceId":"PcmFpaHPCReNp1BD","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pack-breaker","name":"Pack Breaker","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can deceive creatures by changing their perception of their allies' behavior. Each affected creature suspects their allies have changed allegiance, depending on the outcome of their Will save. Regardless of the effects of the saving throw, the creature is then temporarily immune to pack breaker for 1 hour.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature becomes to all creatures to which it wasn't already hostile, even those that were previously allies. It treats no one as an ally for 1 minute. Each of its former allies within its reach must attempt a save against pack breaker.\n\nFailure As success, but the creature is also for 1 round.\n\nCritical Failure As success, but the creature is confused for 1 minute.","source":{"provider":"PAIZO","sourceId":"cGGEi67G1RStR9cD","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pillars-of-sand","name":"Pillars of Sand","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You raise one or more pillars of solid sand from the earth. The total height of the pillars is 30 feet, which must be used in 10-foot increments (for example, you could create three 10-foot-tall pillars, one 20-foot-tall pillar and one 10-foot-tall pillar, or one 30-foot-tall pillar). Each pillar is 5 feet by 5 feet in length and width. The pillars must be conjured on a relatively flat area of natural earthen terrain such as sand, dirt, stone, or clay. Regardless of the terrain, the pillars are always made of tightly compacted sand particles that together become as hard and solid as stone (athletics to Climb).\n\nIf a creature occupies the space where you cast this spell, it is carried upward atop the pillar. The creature can attempt a Reflex save (DC equal to the caster's spell DC); on a success, the creature can either attempt to Grab an Edge or move into an adjacent unoccupied square. If the pillar would rise higher than the ceiling, it firmly abuts the ceiling but does not rise any higher. A creature caught between a pillar and a ceiling takes no damage (subject to GM discretion, such as is in the case of stalactites or other hazards) but becomes immobilized. The creature can attempt an Escape check to free itself, but it must thereafter Grab an Edge, Climb down, or fall from the top of the pillar. The Grab an Edge and Escape DCs are the same as the Reflex save.\n\nAs part of your action to Sustain the Spell, you can choose to either destroy one of your pillars, causing it to immediately crumble into nothing, or create a new pillar, as long as doing so wouldn't exceed the total number of feet of pillar you can create. You can Sustain the Spell two or more times on a single turn to destroy or create a pillar.\n\nHeightened (+1) The total height of the pillars increases by 10 feet, but must still be used in 10-foot increments (this also increases the total number of pillars that can be created by one).","source":{"provider":"PAIZO","sourceId":"qr0HOiiuqj5LKlDt","book":"Pathfinder #155: Lord of the Black Sands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.plague-shot","name":"Plague Shot","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["disease"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"}},"targeting":{"range":{"kind":"TOUCH"},"target":"10 pieces of siege weapon ammunition, such as a ballista bolt or catapult stone","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Medicine (expert)","secondaryChecks":"Warfare Lore","secondaryCasters":1},"description":"You imbue several pieces of siege weapon ammunition with an infectious disease that can bring an opposing force low over time. Once the ritual is successfully concluded, the affected pieces of ammunition glow a sickly green and must be launched within the hour or the enchantment fades. In addition to its normal damage or other effects, a successful attack with a piece of the affected ammunition exposes every creature within a 60-foot-radius emanation from the point of impact to siege sickness.\n\nSiege Sickness (disease) Level 8\n\nSaving Throw fortitude\n\nOnset 1 day\n\nStage 1 Sickened 2 (1 day)\n\nStage 2 Enfeebled 1 and sickened 2 (1 day)\n\nStage 3 Enfeebled 2 and Sickened 3 (1 day)\n\nStage 4 Enfeebled 3, sickened 3, and a creature who comes into physical contact with the afflicted is exposed to siege sickness (1 day)\n\nStage 5 death, and a creature who comes into physical contact with the corpse is exposed to siege sickness\nCritical Success The siege sickness gains the virulent trait.\n\nSuccess The siege sickness is normal.\n\nFailure The ritual has no effect.\n\nCritical Failure Instead of being imbued in the ammunition, the disease becomes airborne at the site of the ritual. Each creature within a 60-foot emanation centered on the primary caster is exposed to siege sickness at stage 2.","source":{"provider":"PAIZO","sourceId":"NjN6md0KpdelWpu7","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.planar-servitor","name":"Planar Servitor","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense and offerings worth a total value of 2 gp × the spell rank × the target's level, see text for more details"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert)","secondaryChecks":"Diplomacy","secondaryCasters":2},"description":"You call upon a deity (or other divine power) to grant you aid in the form of a divine servitor of your deity's choice, with a level no greater than double the ritual's spell rank. The secondary casters explain what sort of assistance you need and why you need it; if the task is incredibly fitting to the deity, the GM can grant a circumstance bonus to the secondary Diplomacy check or rule that the check is automatically a critical success. If you use the ritual without good reason, the result is automatically a critical failure.\n\nIf the ritual succeeds, you must offer the servitor payment depending on factors such as the duration and danger of the task. Payment always costs at least as much as a consumable item of the creature's level, and often costs as much as a permanent magic item of the creature's level to persuade a creature to fight alongside you. Your offerings should align with the personal tastes of the deity.\n\nYou can alternatively name a being native to the deity's realm that you know personally, with the same level restriction. Such a creature might request something they personally want as payment.\n\nCritical Success The deity sends a servitor, and the servitor's payment costs only half as much as normal. If you ask for a particular servitor by name, the deity is likely to send that servitor unless the servitor is busy.\n\nSuccess Your deity sends a servitor.\n\nFailure Your deity does not send a servitor.\n\nCritical Failure The deity is offended and sends a sign of displeasure or possibly even a servitor to scold or attack you, depending on your deity's nature. A deity might also opt to strip divine powers from its followers who participated until they atone","source":{"provider":"PAIZO","sourceId":"vgy00hnqxN9VoeoF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.plant-form","name":"Plant Form","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","plant","polymorph","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Taking inspiration from verdant creatures, you transform into a Large plant battle form. When you Cast this Spell, choose a listed battle form. You can substitute a similar specific plant to turn into (such as a pitcher plant instead of a flytrap), but this has no effect on the form's Size or statistics. While in this form, you gain the plant trait. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n\n- AC = 19 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 12 temporary Hit Points.\n\n- Resistance 10 to poison.\n\n- Low-light vision.\n\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +17, and your damage bonus is +11. These attacks are Strength based (for the purpose of the condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n\n- Athletics modifier of +19, unless your own modifier is higher.\n\nYou also gain specific abilities based on the type of plant you choose:\n\n- Arboreal\n\n- Speed 30 feet\n\n- Melee 1 branch (reach 15 feet), Damage 2d10 bludgeoning;\n\n- Melee 1 foot, Damage 2d8 bludgeoning;\n\n- you can speak in this form\n\n- Flytrap\n\n- Speed 15 feet; resistance 10 to acid;\n\n- Melee 1 leaf (reach 10 feet), Damage 2d8 piercing, and you can spend an action after a hit to Grab the target.\n\nHeightened (6th) Your battle form is Huge, and the reach of your attacks increases by 5 feet. You instead gain AC = 22 + your level, 24 temporary HP, attack modifier +21, damage bonus +16, and Athletics +22.","source":{"provider":"PAIZO","sourceId":"zCcfPS4y5SrZzU2x","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
